      for (int neighbor = 0; neighbor < 9; neighbor++) {
        vec2 tile = cell + vec2(float(neighbor - 3*(neighbor/3)) - 1.0, float(neighbor/3) - 1.0);
        vec2 key = tile + vec2(z*79.3 + float(kind)*117.1, z*21.1 + float(kind)*31.7);
        float seed = hash2(key);
        if (seed > intensity * 0.8) continue;
        vec2 at = tile + vec2(hash2(key+vec2(13.1,z)), hash2(key+vec2(z,9.7)));
        vec2 rel = (q-at) / grid;
        float alpha = 0.0;
        vec3 color = uData[27].xyz;
        if (kind == 0) {
          vec2 line = down * (0.025 + depth * 0.09) * uData[28].y;
          float h = sat(dot(rel,line) / max(dot(line,line),0.000001));
          float d = length(rel-line*h);
          alpha = cover(d - (0.00065+depth*0.0015)*uData[28].y,px) * 0.28 * depth;
          color = mix(uData[27].xyz, vec3(0.72,0.82,0.9),0.75);
        } else if (kind == 1) {
          float radius = (0.004+depth*0.009) * uData[26].y * (0.7 + seed*0.5);
          vec2 flake = rotate2(rel / radius, seed*6.283 + time*(seed-0.5)*movement);
          float a = atan2(flake.y,flake.x);
          float branches = 0.6 + 0.25*cos(a*6.0) + 0.08*cos(a*12.0+seed*8.0);
          alpha = cover(length(flake)-branches,px/radius) * 0.7 * depth;
        } else {
          alpha = cover(length(rel)-(0.003+depth*0.007)*uData[38].w,px) * 0.85 * depth;
          color = vec3(uData[39].z, uData[39].w, uData[40].x);
        }
        c = over(c,color,alpha*uData[41].w);
      }
    }
  }
  return c;
}
vec4 frostWeather(constant float4* uData, vec4 c, vec2 p, float px, float time) {
  float amount = uData[49].w;
  if (amount <= 0.0) return c;
  float patches = fbm(p*5.0,5);
  float edge = pow(sat(dot(p,p)),2.0);
  float glaze = smoothstep(0.9-amount*0.85,1.05-amount*0.65,patches+edge*0.4);
  float angle = atan2(p.y,p.x);
  float crystals = pow(max(0.0,sin(angle*18.0+fbm(p*9.0,3)*6.0)),12.0) * edge;
  float scatter = mix(0.15,0.75,uData[40].z);
  float grain = vnoise(p*120.0) * (1.0-smoothstep(0.003,0.012,px));
  c = over(c,uData[41].xyz,glaze*(scatter+grain*0.12));
  c.rgb += uData[41].xyz * crystals * glaze * 0.09;
  return c;
}

// How much of pool i reaches p: each wanders its own slow loop.
float pool(vec2 p, float t, float i, float scale, float blur) {
  vec2 at = 0.58 * vec2(sin(t * (0.43 + 0.11 * i) + i * 1.9), cos(t * (0.37 + 0.09 * i) + i * 2.7));
  // Convolving a Gaussian pool widens it and lowers its peak, keeping its colour energy.
  float area = scale * scale;
  float diffused = area + 2.0 * blur * blur;
  vec2 d = p - at;
  return exp(-dot(d, d) * 1.6 / diffused) * area / diffused;
}

vec4 orbContents(constant float4* uData, vec2 s, vec2 face, float w, float k, float blur, float level, vec4 clock, vec4 m) {
  float t = m.x;
  float pulse = uData[48].x * level;
  vec2 p = rotate2(s, -m.y * 0.01745329);
  // Swirl the colours into each other, twice over at two scales.
  float warp = uData[47].z * (1.0 + 0.5 * pulse);
  p += warp * 0.3 * vec2(sin(p.y * 2.3 + t * 0.9), sin(p.x * 2.1 - t * 1.1));
  p += warp * 0.15 * vec2(sin(p.y * 4.7 - t * 1.3 + 1.7), sin(p.x * 4.1 + t * 0.8 + 0.6));
  float scale = uData[47].y * (1.0 + 0.4 * pulse);
  float a = pool(p, t, 0.0, scale, blur);
  float b = pool(p, t, 1.0, scale, blur);
  float c = pool(p, t, 2.0, scale, blur);
  float d = pool(p, t, 3.0, scale, blur);
  float base = 0.12;
  vec3 col = (uData[46].xyz * base + uData[43].xyz * a + vec3(uData[43].w, uData[44].x, uData[44].y) * b
    + vec3(uData[44].z, uData[44].w, uData[45].x) * c + uData[45].yzw * d) / (base + a + b + c + d);
  // The middle glows, as light gathered in the glass.
  float coreSpread = 1.0 + 2.0 * blur * blur;
  float core = uData[47].w * (1.0 + pulse) * exp(-dot(s, s) * 2.2 / coreSpread) / coreSpread;
  col = mix(col, min(col * 1.5 + 0.2, vec3(1.0)), sat(core));
  return vec4(col, 1.0);
}

// What shows through the glass at a point of the face: the contents, bent by the glass, over the
// room seen through the ball. scale bends one channel a little more or less, for dispersion; blur
// is the frosting on the face.
vec3 insideAt(constant float4* uData, vec2 face, float px, float level, vec4 clock, vec4 m, float scale, float blur) {
  vec3 un = unbend(face, uData[4].z * scale);
  vec4 c = orbContents(uData, un.xy, face, 0.75 * px / un.z, 1.0 / un.z, blur / un.z, level, clock, m);
  c = weatherSky(uData, c, un.xy, px, clock);
  if (c.a >= 0.999) return c.rgb;
  vec3 behind = throughBall(face, 1.0 + (uData[4].w - 1.0) * scale);
  return c.rgb + room(uData, behind, blur, clock.z * 0.01745329) * (1.0 - c.a);
}

// Where a drop looks: a bead of water is a lens, gathering a wide patch of the view behind it,
// upside down. drop is its centre and radius; q is this point in the drop, -1 to 1.
vec2 dropLook(constant float4* uData, vec3 drop, vec2 q) {
  return drop.xy - q * uData[16].x;
}

// The drop's colour, from the glass under it (col) and what its lens gathers (seen).
vec3 dropView(constant float4* uData, vec3 col, vec3 seen, vec3 drop, vec2 q) {
  return mix(col, seen, 0.8);
}

vec4 weatherView(constant float4* uData, vec2 frag, vec4 head, vec4 clock) {
  float unit = max(1.0,head.y*0.5);
  vec2 p = (frag-head.xy*0.5)/unit;
  float px = 1.0/(unit*head.w);
  vec4 c = uData[49].y < 1.5 ? vec4(mix(vec3(uData[12].w, uData[13].x, uData[13].y),uData[12].xyz,sat(p.y*0.5+0.5)),1.0) : vec4(0.0);
  if (uData[49].y < 1.5) {
    vec4 contents = orbContents(uData, p,p,px,1.0,0.0,head.z,clock,uData[2]);
    c = contents + c * (1.0-contents.a);
    c = weatherSky(uData, c,p,px,clock);
    if (((mod(floor(uData[49].z / 8.0), 2.0) > 0.5)) && (uData[31].x > 0.0)) { c = weatherLightning(uData, c,p,px,clock); }
  }
  else {
    if (((mod(floor(uData[49].z / 4.0), 2.0) > 0.5)) && (uData[30].w > 0.0)) {
    float opacity = (1.0-exp(-3.912*uData[35].y/max(50.0,uData[35].x)))*uData[34].w;
    c = over(c,vec3(uData[35].w, uData[36].x, uData[36].y),opacity);
    }
    if (((mod(floor(uData[49].z / 8.0), 2.0) > 0.5)) && (uData[31].x > 0.0)) {
    c = weatherLightning(uData, c,p,px,clock);
    }
  }
  if (((mod(floor(uData[49].z / 64.0), 2.0) > 0.5)) && (uData[31].w > 0.0)) { c = airborneWeather(uData, c,p,px,clock.x); }
  return c;
}

// Rain on the inside of the glass. Drops sit where they landed. Running drops stick and slip down
// it, leaving a streak of water that beads up behind them, and a path clear of fog and mist.
// Every drop casts a shadow; the water a point sits in (drops rarely overlap, so one is enough) is
// a lens.

// A drop as the glass shows it: smaller toward the rim, where the glass curves away, and fading
// there, so one running off the bottom and back on at the top never pops. Centre, radius, alpha.


// Water joins only at contact, matching the simulation. A small smoothing zone rounds the neck
// while the smaller drop retracts into the larger one.

// Keep the two drops face sits deepest in, by how deep (k, |q|): hit and next, how deep each in
// near. The first counts out to where merging or its edge's anti-aliasing reaches, the second out
// to where merging does.
void consider(vec4 d, float k, float reach, thread vec4& hit, thread vec4& next, thread vec2& near) {
  if (k < near.x && k < reach) {
    next = hit;
    near.y = near.x;
    hit = d;
    near.x = k;
  } else if (k < near.y && k < 1.03) {
    next = d;
    near.y = k;
  }
}

// The water face is in, from the two drops it sits deepest in (see consider): as a drop, with its
// alpha the share of face it covers. Where two touch, they are one: each a dome of water, the two
// joined by a smooth maximum, so they fill in where they meet, and the slope turns from the one to
// the other.
vec4 water(vec2 face, float px, vec4 a, vec4 b, vec2 near) {
  if (a.w <= 0.0) return vec4(0.0);
  float ra = abs(a.z);
  vec2 qa = (face - a.xy) / ra;
  if (near.y >= 1.03 || b.w <= 0.0) return vec4(a.xyz, a.w * cover((length(qa) - 1.0) * ra, px));
  float rb = abs(b.z);
  vec2 qb = (face - b.xy) / rb;
  float ea = 0.5 * ra * (1.0 - dot(qa, qa));
  float eb = 0.5 * rb * (1.0 - dot(qb, qb));
  float soft = 0.05 * min(ra, rb);
  float l = sat(0.5 + 0.5 * (ea - eb) / soft);
  float e = mix(eb, ea, l) + soft * l * (1.0 - l);
  vec2 q = mix(qb, qa, l);
  float s = mix(rb, ra, l);
  float k = sqrt(max(0.0, 1.0 - 2.0 * e / s));
  float film = l < 0.5 ? b.z : a.z;
  return vec4(face - q * s, film < 0.0 ? -s : s, mix(b.w, a.w, l) * cover((k - 1.0) * s, px));
}

// Surface discs share their geometry with the simulation's contact test.
vec2 pathPoint(float code) {
  float a = floor(code / 4096.0);
  return vec2(a, code - a * 4096.0) / 4095.0 * 2.4 - 1.2;
}
// Each lobe has 12 bits of direction and 12 of deformation, with no coarse shape steps.
vec3 dropShape(float code) {
  float drive = floor(code / 4096.0) / 4095.0;
  if (drive <= 0.0) return vec3(0.0, -1.0, 0.0);
  float angle = (code - floor(code / 4096.0) * 4096.0) / 4095.0 * 6.28318530718 - 3.14159265359;
  return vec3(cos(angle), sin(angle), drive);
}

// A moving footprint stretches with velocity and narrows toward its trailing contact line.
// The analytic derivative includes that taper, so the outline and optical slope stay consistent.
vec3 dropField(vec2 face, vec3 d, vec3 shape) {
  vec2 rel = face - d.xy;
  float radial = length(d.xy);
  vec2 axis = radial > 0.001 ? d.xy / radial : vec2(0.0, 1.0);
  float z = sqrt(max(0.025, 1.0 - dot(d.xy, d.xy)));
  vec2 tangent = rel + axis * dot(rel, axis) * (1.0 / z - 1.0);
  vec2 direction = shape.xy + axis * dot(shape.xy, axis) * (1.0 / z - 1.0);
  direction /= max(length(direction), 0.00001);
  vec2 side = vec2(-direction.y, direction.x);
  float along = dot(tangent, direction);
  float across = dot(tangent, side);
  float stretch = 1.0 + 0.32 * shape.z;
  float shifted = along + 0.06 * shape.z * d.z;
  float u = shifted / (d.z * stretch);
  float taper = 1.0 + 0.14 * shape.z * clamp(u, -1.0, 1.0);
  float taperSlope = abs(u) < 1.0 ? 0.14 * shape.z / (d.z * stretch) : 0.0;
  float qa = shifted / stretch;
  float qb = across * sqrt(stretch) / taper;
  float len = sqrt(qa * qa + qb * qb);
  float ga = (qa / stretch - qb * across * sqrt(stretch) * taperSlope / (taper * taper)) / max(len, 0.00001);
  float gb = qb * sqrt(stretch) / taper / max(len, 0.00001);
  vec2 grad = direction * ga + side * gb;
  grad += axis * dot(grad, axis) * (1.0 / z - 1.0);
  return vec3(len - d.z, grad);
}

// Contact tension reshapes a lobe toward the neck while its far contact line briefly stays
// on the glass. This tangent-plane warp preserves area, including the original moving shape.
// Transform its analytic gradient with the same warp so the entire optical surface responds.
vec3 contactField(vec2 face, vec3 d, vec3 shape, vec2 toward, float tension) {
  if (tension <= 0.0) return dropField(face, d, shape);
  float radial = length(d.xy);
  vec2 axis = radial > 0.001 ? d.xy / radial : vec2(0.0, 1.0);
  float z = sqrt(max(0.025, 1.0 - dot(d.xy, d.xy)));
  vec2 direction = toward + axis * dot(toward, axis) * (1.0 / z - 1.0);
  direction /= max(length(direction), 0.00001);
  vec2 side = vec2(-direction.y, direction.x);
  vec2 point = face - d.xy;
  point += axis * dot(point, axis) * (1.0 / z - 1.0);
  float stretch = 1.0 + 0.28 * tension;
  float offset = (stretch - 1.0) * d.z;
  vec2 mapped = direction * ((dot(point, direction) - offset) / stretch)
    + side * dot(point, side) * stretch;
  mapped += axis * dot(mapped, axis) * (z - 1.0);
  vec3 field = dropField(d.xy + mapped, d, shape);
  vec2 grad = field.yz;
  grad += axis * dot(grad, axis) * (z - 1.0);
  grad = direction * (dot(grad, direction) / stretch) + side * dot(grad, side) * stretch;
  grad += axis * dot(grad, axis) * (1.0 / z - 1.0);
  return vec3(field.x, grad);
}

// Height and gradient of the water cap above its footprint. Combining footprint distances
// alone leaves the small lobe's steep optical slope intact, even after it is inside the head.
// Combine these heights instead, so the advancing surface covers and relaxes that little bump.
vec3 dropCap(vec3 field, float radius) {
  float k = max(0.0, 1.0 + field.x / radius);
  return vec3(0.5 * radius * (1.0 - k * k), -field.yz * k);
}

// A contacting pair has one water height and one optical normal. The smooth maximum rounds
// its meniscus, and its derivative supplies the slope across both lobes and the connection.
void sphereWater(vec2 face, float px, vec4 a, vec4 b, float neck, vec2 codes,
                 thread vec4& liquid, thread float& deepest, thread float& shadow) {
  if (a.z <= 0.0 || a.w <= 0.0) return;
  vec2 reach = vec2(2.25 * a.z + neck + px);
  vec2 lo = a.xy - reach;
  vec2 hi = a.xy + reach;
  if (b.z > 0.0) {
    lo = min(lo, b.xy - vec2(2.25 * b.z + neck + px));
    hi = max(hi, b.xy + vec2(2.25 * b.z + neck + px));
  }
  // Include the small exterior shadow without evaluating distant footprints.
  if (face.x < lo.x - a.z || face.y < lo.y - a.z || face.x > hi.x + a.z || face.y > hi.y + a.z) return;
  vec3 shapeA = dropShape(codes.x);
  vec3 shapeB = dropShape(codes.y);
  vec3 field = dropField(face, a.xyz, shapeA);
  vec3 surface = dropCap(field, a.z);
  // Shadows follow the real footprint, rather than the virtual refraction centre. That centre
  // changes at every fragment and used to extend the shadow into a hard column below the water.
  float shadowDistance = dropField(face + vec2(0.0, 0.22 * a.z), a.xyz, shapeA).x;
  float shadowSize = a.z;
  float size = a.z;
  float alpha = a.w;
  if (b.z > 0.0) {
    vec2 toward = b.xy - a.xy;
    toward = length(toward) > 0.00001 ? toward / length(toward) : vec2(0.0, -1.0);
    float atContact = dropField(b.xy, a.xyz, shapeA).x;
    // Catch on the first visible touch, before volume begins draining. Let that strain relax
    // as the small lobe is enveloped; the smaller body supplies most of the shape response.
    float touching = 1.0 - smoothstep(0.0, 2.0 * px, atContact - b.z);
    float uncovered = smoothstep(-b.z, 0.0, atContact);
    float strain = (0.22 + 0.78 * smoothstep(0.08, 0.5, neck / b.z)) * touching * uncovered;
    float share = b.z * b.z / (a.z * a.z + b.z * b.z);
    float tensionA = strain * share;
    float tensionB = strain * (1.0 - share);
    field = contactField(face, a.xyz, shapeA, toward, tensionA);
    surface = dropCap(field, a.z);
    shadowDistance = contactField(face + vec2(0.0, 0.22 * a.z), a.xyz, shapeA, toward, tensionA).x;
    vec3 other = dropCap(contactField(face, b.xyz, shapeB, -toward, tensionB), b.z);
    float otherShadow = contactField(face + vec2(0.0, 0.22 * b.z), b.xyz, shapeB, -toward, tensionB).x;
    if (otherShadow < shadowDistance) { shadowDistance = otherShadow; shadowSize = b.z; }
    float soft = max(min(neck, b.z) * uncovered, 0.000001);
    float h = sat(0.5 + 0.5 * (surface.x - other.x) / soft);
    surface = vec3(mix(other.x, surface.x, h) + soft * h * (1.0 - h), mix(other.yz, surface.yz, h));
    size = mix(b.z, a.z, h);
    alpha = max(a.w, b.w);
    // A connection spans exposed water; it must not leave its own rounded endpoint at the
    // donor's old centre after the head has covered it. Limit it to the remaining lobe and
    // relax it away as that contact point is enveloped by the advancing footprint.
    float gap = contactField(b.xy, a.xyz, shapeA, toward, tensionA).x - b.z * (1.0 + 0.56 * tensionB);
    float exposed = smoothstep(-b.z, 0.0, gap);
    float bridgeRadius = min(neck, b.z) * exposed;
    if (bridgeRadius > 0.000001) {
      vec2 segment = b.xy - a.xy;
      float u = clamp(dot(face - a.xy, segment) / max(dot(segment, segment), 0.000001), 0.0, 1.0);
      vec3 bridge = dropField(face, vec3(a.xy + segment * u, bridgeRadius), vec3(0.0, -1.0, 0.0));
      if (u > 0.0 && u < 1.0) bridge.yz -= segment * dot(bridge.yz, segment) / max(dot(segment, segment), 0.000001);
      bridge = dropCap(bridge, bridgeRadius);
      float rounding = max(0.5 * bridgeRadius, 0.000001);
      float join = sat(0.5 + 0.5 * (surface.x - bridge.x) / rounding);
      surface = vec3(mix(bridge.x, surface.x, join) + rounding * join * (1.0 - join), mix(bridge.yz, surface.yz, join));
      size = mix(bridgeRadius, size, join);
    }
  }
  float radial = length(face);
  alpha *= 1.0 - smoothstep(0.97, 1.08, radial);
  float distance = b.z > 0.0 ? -surface.x : field.x;
  float edge = max(px, px * length(b.z > 0.0 ? surface.yz : field.yz));
  alpha *= sat(size / px);
  float coverage = alpha * cover(distance, edge);
  // One height gradient supplies every optical cue. A small lobe that the advancing cap has
  // enveloped no longer contributes a separate spherical highlight or a steep little rim.
  vec2 q = -surface.yz;
  // Project the tangent normal into the view. Screen-space distance derivatives grow toward
  // the rim; feeding them straight into refraction made the water look like a rigid sharp edge.
  vec2 axis = radial > 0.001 ? face / radial : vec2(0.0, 1.0);
  q += axis * dot(q, axis) * (max(0.025, 1.0 - dot(face, face)) - 1.0);
  q *= 0.8;
  vec4 lens = vec4(face - q * size, size, alpha);
  shadow *= 1.0 - 0.08 * alpha * cover(shadowDistance, max(px, 0.18 * shadowSize));
  float depth = -surface.x;
  if (coverage > 0.0 && depth < deepest) {
    liquid = vec4(lens.xyz, coverage);
    deepest = depth;
  }
}

// Each wiped point keeps its scene time. Completed chunks remain until the fog has returned;
// movement at the head cannot refresh the old tail or evict it while it is still clear.
void rainTrail(vec2 face, float px, float now, vec4 p0, vec4 p1, vec4 p2,
               vec4 t0, vec4 t1, vec4 t2, vec4 meta, float alpha,
               thread vec4& hit, thread vec4& next, thread vec2& near, thread float& wipe) {
  float r = meta.x;
  if (r <= 0.0 || alpha <= 0.0) return;
  vec2 pts[12];
  pts[0] = pathPoint(p0.x); pts[1] = pathPoint(p0.y); pts[2] = pathPoint(p0.z); pts[3] = pathPoint(p0.w);
  pts[4] = pathPoint(p1.x); pts[5] = pathPoint(p1.y); pts[6] = pathPoint(p1.z); pts[7] = pathPoint(p1.w);
  pts[8] = pathPoint(p2.x); pts[9] = pathPoint(p2.y); pts[10] = pathPoint(p2.z); pts[11] = pathPoint(p2.w);
  float times[12];
  times[0] = t0.x; times[1] = t0.y; times[2] = t0.z; times[3] = t0.w;
  times[4] = t1.x; times[5] = t1.y; times[6] = t1.z; times[7] = t1.w;
  times[8] = t2.x; times[9] = t2.y; times[10] = t2.z; times[11] = t2.w;
  float z = sqrt(max(0.04, 1.0 - dot(face, face)));
  float humidity = 6.0 + 2.0 * vnoise(face * 9.0);
  float closest = 1000.0;
  vec2 delta = vec2(0.0);
  vec2 tangent = vec2(0.0, -1.0);
  float deposited = 0.0;
  for (int k = 0; k < 11; k++) {
    if (float(k + 1) >= meta.z) break;
    vec2 seg = pts[k + 1] - pts[k];
    float len2 = dot(seg, seg);
    if (len2 < 0.000001) continue;
    float h = clamp(dot(face - pts[k], seg) / len2, 0.0, 1.0);
    vec2 d = face - pts[k] - seg * h;
    float distance = length(d);
    if (distance > r + px) continue;
    float age = max(0.0, now - mix(times[k], times[k + 1], h));
    float wet = 1.0 - smoothstep(0.35, humidity, age);
    float clearing = r * z * (0.72 + 0.13 * vnoise(face * 42.0)) * mix(0.45, 1.0, wet);
    wipe = max(wipe, alpha * wet * cover(distance - clearing, max(px, 0.08 * r)));
    // Choose the nearest centreline before ageing or shading it. Picking the freshest capsule
    // made every saved anchor produce a round lens endpoint and a regularly spaced optical rib.
    if (distance < closest) {
      closest = distance;
      delta = d;
      deposited = age;
      vec2 direction = seg / sqrt(len2);
      vec2 before = k > 0 ? pts[k] - pts[k - 1] : seg;
      vec2 after = float(k + 2) < meta.z ? pts[k + 2] - pts[k + 1] : seg;
      before /= max(length(before), 0.0001);
      after /= max(length(after), 0.0001);
      // Shared tangents round small bends without drawing a separate cap at every path sample.
      vec2 joined = mix(direction + before, direction + after, smoothstep(0.0, 1.0, h));
      tangent = length(joined) > 0.001 ? normalize(joined) : direction;
    }
  }
  if (closest < r + px) {
    vec2 centre = face - delta;
    // Deposited water pinches and spreads over fixed glass patches. The variation stays on the
    // glass as the head moves; a shallow transverse slope reads as film rather than a bead tube.
    float width = r * z * (0.08 + 0.12 * vnoise(centre * vec2(23.0, 17.0) + vec2(4.7, 9.2)));
    float fresh = 1.0 - smoothstep(0.15, 2.5, deposited);
    float film = alpha * fresh * cover(closest - width, px) * 0.5;
    if (film > 0.0) {
      vec2 across = vec2(-tangent.y, tangent.x);
      vec2 q = across * (dot(delta, across) / max(width, 0.0001)) * 0.3;
      consider(vec4(face - q * width, -width, film), closest / width, max(1.03, 1.0 + px / width), hit, next, near);
    }
  }
}


vec3 snowMaterial(float phase) {
  if (phase > 0.0) return vec3(1.0, 0.0, 0.0);
  float code = -phase - 1.0;
  float drive = floor(code / 262144.0);
  code -= drive * 262144.0;
  float compact = floor(code / 1024.0);
  return vec3((code - compact * 1024.0) / 1023.0, compact / 255.0, drive / 63.0);
}
float snowSegment(vec2 p, vec2 a, vec2 b) {
  vec2 d = b - a;
  return length(p - a - d * clamp(dot(p - a, d) / max(dot(d, d), 0.000001), 0.0, 1.0));
}
float snowCrystal(vec2 p, vec2 seed, float ice) {
  float family = hash2(seed + vec2(12.7, 31.9));
  float direction = floor((atan2(p.y, p.x) + 0.5235988) / 1.04719755);
  vec2 q = rotate2(p, -direction * 1.04719755);
  q.y = abs(q.y);
  vec2 armSeed = seed + vec2(mod(direction + 6.0, 6.0) * 13.1, 7.3);
  float arm = (0.72 + 0.28 * hash2(armSeed)) * (0.28 + 0.72 * ice);
  float thickness = (0.012 + 0.025 * hash2(seed + vec2(8.1, 3.6))) * smoothstep(0.0, 0.3, ice);
  float d = snowSegment(q, vec2(0.0), vec2(arm, 0.0)) - thickness;
  for (int k = 0; k < 4; k++) {
    float at = (0.17 + 0.16 * float(k)) * arm;
    float side = (0.09 + 0.21 * hash2(seed + vec2(float(k) * 4.7 + 15.9, 10.2)))
      * (1.0 - float(k) * 0.13) * smoothstep(0.15 + float(k) * 0.06, 0.75, ice);
    side *= 0.72 + 0.28 * hash2(armSeed + vec2(float(k) * 6.7, 12.3));
    d = min(d, snowSegment(q, vec2(at, 0.0), vec2(at + side * 0.5, side * 0.8660254)) - thickness * 0.62);
    if (family >= 0.24 && family <= 0.88) {
      for (int twig = 0; twig < 2; twig++) {
        float along = 0.38 + float(twig) * 0.3;
        vec2 base = vec2(at, 0.0) + vec2(0.5, 0.8660254) * side * along;
        float fine = side * (0.2 + 0.12 * hash2(armSeed + vec2(float(k), float(twig))))
          * smoothstep(0.45, 0.95, ice);
        d = min(d, snowSegment(q, base, base + vec2(fine, 0.0)) - thickness * 0.32);
      }
    }
  }
  // Plates, dendrites and rimed crystals share hexagonal geometry but have different cores.
  float core = (family < 0.24 ? 0.48 : (family > 0.88 ? 0.33 : 0.14)) * pow(max(ice, 0.0), 0.3333333);
  float hex = max(q.x * 0.8660254 + q.y * 0.5, q.y) - core;
  if (family < 0.24) d = min(d, hex);
  else d = min(d, length(p) - core * (0.8 + 0.2 * vnoise(p * 12.0 + seed)));
  return d;
}

// A shared height and gradient join nearby wet caps. Keep signed height outside each footprint
// so the smooth union can round a contact neck without creating a flat wet rectangle.
void snowWater(constant float4* uData, vec2 face, float px, float amount, thread vec4& liquid,
               thread float& deepest, thread float& shadow, thread float& wipe) {
  if (amount <= 0.0) return;
  vec3 surface = vec3(-1000.0, 0.0, 0.0);
  float size = 0.0;
  vec2 gravity = vec2(sin(uData[15].w * 0.01745329), -cos(uData[15].w * 0.01745329));
  for (int i = 0; i < 64; i++) {
    vec4 flake = uData[1244 + i];
    bool hail = flake.z < 0.0;
    if (hail ? uData[31].y < 0.5 : uData[28].w < 0.5) continue;
    if (flake.y <= 0.0 || flake.w > 0.0) continue;
    vec3 material = snowMaterial(flake.w);
    float radius = flake.y * 0.34 * pow(max(0.0, 1.0 - material.x), 0.3333333);
    if (radius < px * 0.1) continue;
    vec2 centre = pathPoint(flake.x);
    if (length(face - centre) > radius * 2.5 + px * 2.0) continue;
    vec3 field = dropField(face, vec3(centre, radius), vec3(gravity, material.z));
    if (material.x > 0.0 && !hail) {
      // Early meltwater fills the hollows between branches. Its angular pockets round out as
      // the ice support erodes. Transform the same analytic derivative into screen space.
      vec2 rel = face - centre;
      float radial = length(centre);
      vec2 axis = radial > 0.001 ? centre / radial : vec2(0.0, 1.0);
      float z = sqrt(max(0.025, 1.0 - dot(centre, centre)));
      vec2 tangent = rel + axis * dot(rel, axis) * (1.0 / z - 1.0);
      vec2 seed = vec2(mod(abs(flake.z), 4096.0), floor(abs(flake.z) / 4096.0));
      float turn = hash2(seed + vec2(7.3, 9.4)) * 6.2831853;
      float angle = 6.0 * (atan2(tangent.y, tangent.x) + turn);
      float pocket = radius * 0.14 * material.x * (1.0 - 0.5 * material.y);
      field.x += pocket * cos(angle);
      vec2 slope = vec2(-tangent.y, tangent.x) / max(dot(tangent, tangent), 0.000001);
      slope += axis * dot(slope, axis) * (1.0 / z - 1.0);
      field.yz -= pocket * 6.0 * sin(angle) * slope;
    }
    float t = 1.0 + field.x / radius;
    vec3 cap = vec3(0.5 * radius * (1.0 - t * t), -field.yz * t);
    float soft = max(px * 0.08, min(radius, max(size, radius)) * 0.16);
    float h = sat(0.5 + 0.5 * (surface.x - cap.x) / soft);
    surface = vec3(mix(cap.x, surface.x, h) + soft * h * (1.0 - h), mix(cap.yz, surface.yz, h));
    size = mix(radius, size, h);
    shadow *= 1.0 - 0.08 * amount * cover(field.x + radius * 0.12, max(px, radius * 0.12));
  }
  if (size <= 0.0) return;
  float alpha = amount * cover(-surface.x, max(px * 0.35, px * length(surface.yz))) * sat(size / px);
  float radial = length(face);
  alpha *= 1.0 - smoothstep(0.97, 1.06, radial);
  vec2 q = -surface.yz;
  vec2 axis = radial > 0.001 ? face / radial : vec2(0.0, 1.0);
  q += axis * dot(q, axis) * (max(0.025, 1.0 - dot(face, face)) - 1.0);
  q *= 0.8;
  wipe = max(wipe, alpha);
  if (alpha > 0.0 && -surface.x < deepest) {
    liquid = vec4(face - q * size, size, alpha);
    deepest = -surface.x;
  }
}

vec4 snowOver(constant float4* uData, vec4 c, vec2 face, float px, float level) {
  float amount = 1.0;
  if (amount <= 0.0) return c;
  vec3 incoming = lightDir(uData);
  for (int i = 0; i < 64; i++) {
    vec4 flake = uData[1244 + i];
    bool hail = flake.z < 0.0;
    if (hail ? uData[31].y < 0.5 : uData[28].w < 0.5) continue;
    float radius = flake.y;
    if (radius <= 0.0) continue;
    vec2 centre = pathPoint(flake.x);
    if (length(face - centre) > radius * 1.4 + px) continue;
    vec3 material = snowMaterial(flake.w);
    if (material.x <= 0.0) continue;
    vec2 seed = vec2(mod(abs(flake.z), 4096.0), floor(abs(flake.z) / 4096.0));
    float height = max(0.0, flake.w - 1.0);
    vec2 p = (face - centre) / radius;
    float radial = length(centre);
    vec2 axis = radial > 0.001 ? centre / radial : vec2(0.0, 1.0);
    float z = sqrt(max(0.04, 1.0 - dot(centre, centre)));
    p += axis * dot(p, axis) * (mix(1.0 / z, 1.0, sat(height * 5.0)) - 1.0);
    float turn = hash2(seed + vec2(7.3, 9.4)) * 6.2831853 + height * (2.0 + hash2(seed) * 4.0);
    p = rotate2(p, turn);
    // An incoming plate tumbles out of plane and settles flat against the local glass.
    p.x /= mix(1.0, max(0.25, abs(cos(height * (8.0 + 4.0 * hash2(seed)) + turn))), sat(height * 5.0));
    // Compaction integrates dM/M. Undo its bulk radius growth for the original crystal,
    // which stays the same size while deposited material fills the porous space around it.
    float crystalScale = exp(-material.y);
    float crystal = hail ? length(p) - pow(material.x,0.3333333) * (0.88+0.08*vnoise(p*7.0+seed)) : snowCrystal(p / crystalScale, seed, material.x) * crystalScale;
    float mound = length(p) - (0.95 + 0.11 * (vnoise(p * 5.0 + seed) - 0.5)) * pow(material.x, 0.3333333);
    // Packing gradually buries individual branches into a granular deposit, retaining both
    // surfaces through the transition rather than exchanging a flake sprite for a blob.
    float alpha = mix(cover(crystal, px / radius), cover(mound, px / radius), material.y);
    alpha *= amount * smoothstep(0.0, 0.03, material.x) * (1.0 - smoothstep(0.98, 1.08, length(face)));
    alpha *= 1.0 - 0.32 * sat(height * 2.0);
    float grain = vnoise(p * 36.0 + seed) * (1.0 - smoothstep(0.03, 0.2, px / radius));
    vec3 normal = normalize(vec3(centre, z) + vec3(rotate2(vec2(0.1, 0.03), turn), 0.0));
    float illumination = 0.78 + 0.22 * max(0.0, dot(normal, incoming));
    // Thin ice transmits the view; edges, growth ridges and packed grains scatter more light.
    float edge = 1.0 - smoothstep(0.008, 0.045, max(0.0, -crystal));
    float a = atan2(p.y, p.x);
    float folded = mod(a + 0.5235988, 1.04719755) - 0.5235988;
    vec2 q = vec2(length(p) * cos(folded), abs(length(p) * sin(folded)));
    float hex = max(q.x * 0.8660254 + q.y * 0.5, q.y);
    float ridges = exp(-abs(sin(hex * (36.0 + 20.0 * hash2(seed + vec2(9.2, 6.7))))) * 18.0)
      * (1.0 - smoothstep(0.35, 0.65, length(p))) * material.x;
    float scattering = hail ? 0.4 + 0.28*grain + 0.15*max(0.0,1.0-length(p)) : mix(0.42 + 0.48 * edge + 0.1 * ridges, 0.96, material.y);
    vec3 ice = (hail ? vec3(uData[39].z, uData[39].w, uData[40].x) : uData[27].xyz) * illumination * (0.94 + grain * 0.06);
    c = over(c, vec3(0.17, 0.22, 0.29), alpha * 0.1);
    c = over(c, ice, alpha * scattering);
  }
  return c;
}


// The rain at face, before what is behind the glass is drawn. Returns the water face is in, as a
// lens: centre, radius (negative for a streak's film, which catches no glint), and the share of
// face it covers, where the centre is set so that (face - centre) / |radius| is the slope of the
// water at face (for a round drop, just where face is in it). In marks: how clear the running
// drops' paths leave the fog (x) and the mist (y), the light the shadows leave (z), and the light
// the clearer paths the mark draws above its running drops leave (w).
vec4 rainScan(constant float4* uData, vec2 face, float px, vec4 clock, thread vec4& marks) {
  float amount = uData[14].z;
  vec4 hit = vec4(0.0);
  marks = vec4(0.0, 0.0, 1.0, 1.0);
  vec4 next = vec4(0.0);
  vec2 near = vec2(1000.0);
  float shadow = 1.0;
  float wipe = 0.0;
  vec4 counts = uData[51];
  if ((mod(floor(uData[3].w / 1.0), 2.0) > 0.5) || (mod(floor(uData[3].w / 2.0), 2.0) > 0.5) || (mod(floor(uData[49].z / 128.0), 2.0) > 0.5)) {
  for (int i = 0; i < 48; i++) {
    vec4 meta = uData[860 + i * 8 + 6];
    if (meta.x <= 0.0 || meta.z < 2.0) continue;
    vec4 box = uData[860 + i * 8 + 7];
    float reach = meta.x + px;
    if (face.x < box.x - reach || face.y < box.y - reach || face.x > box.z + reach || face.y > box.w + reach) continue;
    float alpha = meta.y == -3.0 ? uData[31].y : meta.y == -2.0 ? uData[28].w : uData[28].z;
    rainTrail(face, px, clock.x,
      uData[860 + i * 8],
      uData[860 + i * 8 + 1],
      uData[860 + i * 8 + 2],
      uData[860 + i * 8 + 3],
      uData[860 + i * 8 + 4],
      uData[860 + i * 8 + 5],
      meta, alpha, hit, next, near, wipe);
  }
  }
  vec4 liquid = vec4(0.0);
  float deepest = 1000.0;
  if ((mod(floor(uData[3].w / 65536.0), 2.0) > 0.5)) {
  for (int i = 0; i < 384; i++) {
    vec4 pool = uData[92 + i * 2];
    if (pool.y <= 0.0 || pool.z < 0.0) continue;
    float alpha = i < 16 ? sat(amount * counts.x - float(i)) : 1.0;
    vec4 other = vec4(0.0);
    vec4 cached = uData[92 + i * 2 + 1];
    if (cached.y > 0.0) {
      vec4 pair = cached;
      float partnerAlpha = pair.z < 0.0 ? 1.0 : sat(amount * counts.x - pair.z);
      other = vec4(pathPoint(pair.x), pair.y, partnerAlpha);
    }
    vec2 shapes = vec2(abs(pool.z) - 1.0, cached.w);
    sphereWater(face, px, vec4(pathPoint(pool.x), pool.y, alpha), other, pool.w, shapes,
                liquid, deepest, shadow);
  }
  }
  if ((mod(floor(uData[3].w / 131072.0), 2.0) > 0.5)) {
  snowWater(uData, face, px, 1.0, liquid, deepest, shadow, wipe);
  }
  marks = vec4(wipe, wipe, shadow, 1.0);
  return liquid.w > 0.0 ? liquid : water(face, px, hit, next, near);
}

// A bead of mist (x, y, radius) over c, a how much of it shows.
vec4 mistBead(vec4 c, vec3 bead, float a, vec2 face, float px, vec3 shade) {
  float d = length(face - bead.xy);
  if (a <= 0.0 || d > bead.z + px) return c;
  // Lit up and to the left, shaded at the far edge.
  float g = length(face - bead.xy - vec2(-0.2, 0.3) * bead.z) / bead.z;
  vec3 tint = vec3(1.0);
  float tintA = 0.0;
  if (g < 0.55) {
    float t = g / 0.55;
    tint = mix(vec3(1.0), vec3(1.0, 0.824, 0.69), t);
    tintA = mix(0.9, 0.3, t);
  } else {
    float t = sat((g - 0.55) / 0.45);
    tint = mix(vec3(1.0, 0.824, 0.69), min(shade * 2.0, vec3(1.0)), t);
    tintA = mix(0.3, 0.25, t);
  }
  return over(c, tint, tintA * a * cover(d - bead.z, px));
}

// The rain over the glass, from rainScan: the clearer paths the mark draws, every drop's shadow,
// the water this point is in (hit, its alpha how much of the point it covers) with seen what its
// lens gathers, and the mist of beads, gone where a drop has run through it.
vec4 rain(constant float4* uData, vec4 c, vec2 face, float px, vec4 hit, vec3 seen, vec4 marks) {
  float mist = 0.0;
  if ((mod(floor(uData[3].w / 16.0), 2.0) > 0.5)) { mist = uData[14].w; }
  if (hit.w <= 0.0 && mist <= 0.0 && marks.z >= 1.0 && marks.w >= 1.0) return c;
  vec3 shade = uData[16].yzw;
  c = over(c, vec3(1.0), 1.0 - marks.w);
  c = over(c, shade, 1.0 - marks.z);

  if (hit.w > 0.0) {
    float size = abs(hit.z);
    vec2 q = (face - hit.xy) / size;
    float kq = length(q);
    vec3 drop = dropView(uData, c.rgb, seen, vec3(hit.xy, size), q);
    drop = mix(drop, shade, 0.2 * smoothstep(0.45, 1.1, kq));
    if (hit.z > 0.0) {
      // A glint up and to the left, and the light the drop gathers onto its lower edge.
      vec2 gleam = q - vec2(-0.3, 0.35);
      drop = mix(drop, vec3(1.0), 0.55 * exp(-dot(gleam, gleam) * 28.0));
      vec2 r = (q - vec2(0.28, -0.5)) / vec2(0.3, 0.12);
      drop = mix(drop, vec3(1.0), 0.2 * exp(-dot(r, r)));
    }
    c = over(c, drop, hit.w);
  }

  if ((mod(floor(uData[3].w / 16.0), 2.0) > 0.5)) {
  vec4 counts = uData[51];
  float beads = counts.y;
  float left = 1.0 - marks.y;
  // The beads are packed four to three slots, and laid down in order.
  for (int q = 0; q < 32 / 4; q++) {
    float i = float(q * 4);
    if (i >= beads) break;
    vec4 a = uData[68 + 3 * q];
    vec4 b = uData[68 + 3 * q + 1];
    vec4 e = uData[68 + 3 * q + 2];
    c = mistBead(c, a.xyz, sat(mist * beads - i) * left, face, px, shade);
    if (i + 1.0 < beads) c = mistBead(c, vec3(a.w, b.xy), sat(mist * beads - (i + 1.0)) * left, face, px, shade);
    if (i + 2.0 < beads) c = mistBead(c, vec3(b.zw, e.x), sat(mist * beads - (i + 2.0)) * left, face, px, shade);
    if (i + 3.0 < beads) c = mistBead(c, e.yzw, sat(mist * beads - (i + 3.0)) * left, face, px, shade);
  }
  }
  return c;
}

// Condensation develops over fixed glass patches, thickest at the cool rim and lower surface.
// Its clock changes local coverage slowly; the texture itself never slides across the glass.
float fogAt(constant float4* uData, vec2 face, float level, vec4 clock) {
  float amount = sat(uData[17].x + uData[23].w * level);
  if (amount <= 0.0) return 0.0;
  float humidity = vnoise(face * 7.0 + vec2(3.7, 8.1));
  float develop = 0.07 * sin(clock.w * 0.45 + humidity * 6.2831853);
  float thick = fbm(face * 2.0, 4) + 0.2 * humidity + develop
    + 0.25 * smoothstep(0.35, 1.0, length(face)) + 0.1 * sat(-face.y);
  return smoothstep(1.2 - 1.3 * amount, 1.6 - 1.25 * amount, thick)
    * (0.5 + 0.5 * amount) * (0.88 + 0.12 * humidity);
}

// Soft, uneven micro-condensation. Fine detail fades below pixel size instead of becoming a
// field of bright dots; broad variations remain fixed on the glass as wiped paths re-fog.
vec4 fogOver(constant float4* uData, vec4 c, vec2 face, float fog, float px) {
  if (fog <= 0.0) return c;
  float mottled = vnoise(face * 28.0 + vec2(7.1, 2.8)) - 0.5;
  float fine = (vnoise(face * 95.0) - 0.5) * (1.0 - smoothstep(0.003, 0.018, px));
  return over(c, uData[17].yzw, fog * (0.55 + 0.055 * mottled + 0.025 * fine));
}

// Sunshine follows the light and surface. Rays stay aligned with the source; glints are selected
// by the reflected light, with moving water supplying its shared meniscus normal.
vec4 sunny(constant float4* uData, vec4 c, vec2 face, float px, float level, vec4 water) {
  float amount = sat(uData[18].y + uData[24].x * level);
  if (((mod(floor(uData[49].z / 2.0), 2.0) > 0.5)) && (uData[30].z > 0.0)) { amount *= exp(-cloudDensity(uData, face,uData[1].x) * uData[32].y * 3.0); }
  if (amount <= 0.0) return c;
  vec3 sun = vec3(uData[18].z, uData[18].w, uData[19].x);
  vec2 light = vec2(uData[7].y, uData[7].z);
  vec2 d = face - light;
  float dist = length(d);
  float source = max(0.3, uData[8].z);
  float glare = 0.45 * exp(-dist * dist / (0.08 * source * source))
    + 0.28 * exp(-dist * dist / (0.65 * source * source));
  float rays = 0.0;
  if (((mod(floor(uData[3].w / 262144.0), 2.0) > 0.5)) && (uData[19].y > 0.0)) {
  float around = atan2(d.y, d.x + 0.000001);
  rays = 0.6 * pow(0.5 + 0.5 * sin(around * 9.0 + 0.8 * sin(around * 3.0)), 8.0)
    + 0.4 * pow(0.5 + 0.5 * sin(around * 14.0 + 2.0), 12.0);
  rays *= exp(-dist * 2.0) * smoothstep(0.04, 0.24, dist) * uData[19].y;
  }
  // The ghosts lie on the line from the light through the middle.
  float ghosts = 0.0;
  if (((mod(floor(uData[3].w / 524288.0), 2.0) > 0.5)) && (uData[19].w > 0.0)) {
  for (int k = 0; k < 3; k++) {
    float fk = float(k);
    vec2 at = light * (0.25 - 0.6 * fk);
    float r = 0.05 + 0.04 * fk - 0.025 * fk * fk;
    float g = length(face - at) / r;
    ghosts += (0.28 - 0.06 * fk) * exp(-g * g * g * g) + 0.1 * exp(-(g - 1.0) * (g - 1.0) * 36.0);
  }
  }
  c = over(c, sun, sat(amount * (glare + 0.22 * rays + 0.55 * ghosts * uData[19].w)));
  if (((mod(floor(uData[49].z / 1.0), 2.0) > 0.5)) && (uData[19].z > 0.0)) {
  // Sparse surface facets catch the source according to their normal, rather than blinking on
  // unrelated timers. Their positions and roughness are fixed, so a paused scene stays still.
  vec2 cell = floor(face * 22.0);
  float h = hash2(cell + 17.0);
  vec2 at = (cell + 0.5 + (vec2(hash2(cell + 2.3), hash2(cell + 8.9)) - 0.5) * 0.7) / 22.0;
  vec2 q = abs(face - at);
  float thin = max(0.0015, px * 0.65);
  float arm = 0.018 + 0.018 * h;
  float star = max(exp(-q.x / thin - q.y / arm), exp(-q.y / thin - q.x / arm));
  vec3 halfLight = normalize(lightDir(uData) + vec3(0.0, 0.0, 1.001));
  vec2 rough = (vec2(hash2(cell + 4.7), hash2(cell + 6.2)) - 0.5) * 0.3;
  vec3 normal = normalize(vec3(at + rough, sqrt(max(0.02, 1.0 - dot(at, at)))));
  float alignment = pow(max(dot(normal, halfLight), 0.0), 64.0);
  float sparkle = step(h, 0.35) * star * alignment;
  if (water.w > 0.0) {
    // rainScan encodes the analytic height gradient, shared across contacting drops and film.
    // A narrow highlight moves continuously with that surface, including through coalescence.
    vec2 slope = (face - water.xy) / max(abs(water.z), 0.0001);
    vec3 waterNormal = normalize(vec3(face + slope, sqrt(max(0.02, 1.0 - dot(face, face)))));
    float wetGlint = pow(max(dot(waterNormal, halfLight), 0.0), 96.0);
    sparkle = mix(sparkle, 0.75 * wetGlint, water.w);
  }
  sparkle *= uData[19].z;
  return over(c, mix(sun, vec3(1.0), 0.6), sat(amount * sparkle));
  }
  return c;
}

// The room mirrored in the glass, the light's softbox included, by Fresnel: faint face on,
// strong at the rim.
vec4 mirror(constant float4* uData, vec4 c, vec2 face, float blur, vec4 clock) {
  float amount = uData[6].z;
  if (amount <= 0.0) return c;
  vec3 n = vec3(face, sqrt(max(0.0, 1.0 - dot(face, face))));
  vec3 d = reflect(vec3(0.0, 0.0, -1.0), n);
  float ior = uData[4].w;
  float f0 = ((ior - 1.0) / (ior + 1.0)) * ((ior - 1.0) / (ior + 1.0));
  float fresnel = f0 + (1.0 - f0) * pow(1.0 - n.z, 5.0);
  c = over(c, room(uData, d, blur, clock.z * 0.01745329), sat(fresnel * amount));
  // The light is far brighter than the room, so even face on, where little is mirrored, it shows.
  return over(c, vec3(uData[7].w, uData[8].x, uData[8].y), sat((0.25 + fresnel) * 3.0 * amount * softbox(uData, d, blur)));
}

vec4 glass(constant float4* uData, vec4 c, vec2 face, float r, float px) {
  // Light bounced up along the bottom of the glass: a soft arc from -139° to -41°.
  if (((mod(floor(uData[3].w / 2048.0), 2.0) > 0.5)) && (uData[10].x > 0.0)) {
  float angle = atan2(face.y, face.x) * 57.29578;
  float along = smoothstep(-149.0, -131.0, angle) * (1.0 - smoothstep(-49.0, -31.0, angle));
  float band = exp(-((r - 0.94) / 0.1) * ((r - 0.94) / 0.1));
  c = over(c, uData[10].yzw, sat(uData[10].x * 0.2 * band * along));

  }
  if (((mod(floor(uData[3].w / 4096.0), 2.0) > 0.5)) && (uData[9].w > 0.0)) {
  float rim = r < 0.84 ? 0.0 : (r < 0.96 ? mix(0.0, 0.32, (r - 0.84) / 0.12) : mix(0.32, 0.65, sat((r - 0.96) / 0.04)));
  c = over(c, vec3(1.0), sat(rim * uData[9].w));

  // The highlight lies along the curve of the glass where the light is, and the glint beside it,
  // further out. Placed as the mark places them, turned round the middle with the light.
  }
  if ((mod(floor(uData[3].w / 8192.0), 2.0) > 0.5) || (mod(floor(uData[3].w / 16384.0), 2.0) > 0.5)) {
  vec2 light = lightSpot(uData);
  float size = uData[8].z;
  float turn = dot(light, light) > 0.0001 ? atan2(light.y, light.x) - 2.1948194 : 0.0;
  vec3 lit = vec3(uData[7].w, uData[8].x, uData[8].y);
  if (((mod(floor(uData[3].w / 8192.0), 2.0) > 0.5)) && (uData[6].w > 0.0)) {
  float tilt = turn + 0.66322512;
  vec2 h = face - light;
  float ct = cos(tilt);
  float st = sin(tilt);
  float e = length(vec2(h.x * ct + h.y * st, -h.x * st + h.y * ct) / (vec2(0.27, 0.14) * size));
  float spec = e < 0.55 ? mix(0.9, 0.3, e / 0.55) : mix(0.3, 0.0, sat((e - 0.55) / 0.45));
  c = over(c, lit, sat(spec * uData[6].w));
  }
  if (((mod(floor(uData[3].w / 16384.0), 2.0) > 0.5)) && (uData[7].x > 0.0)) {
  vec2 glint = light + rotate2(vec2(-0.11, 0.07), turn) * size;
  c = over(c, lit, sat(uData[7].x) * cover(length(face - glint) - 0.05 * size, px));

  }
  }
  // A fine dark line round the glass keeps the orb's shape on a white page.
  if (((mod(floor(uData[3].w / 32768.0), 2.0) > 0.5)) && (uData[11].x > 0.0)) { c = over(c, uData[11].yzw, uData[11].x * cover(abs(r - 0.99) - 0.01, px)); }
  return c;
}

// Round the orb: its halo, its shadow on the floor with the light it gathers there, and the
// background. Premultiplied.
vec4 outside(constant float4* uData, vec2 face, float r, float level) {
  vec4 under = vec4(0.0);
  if ((mod(floor(uData[3].w / 64.0), 2.0) > 0.5)) {
  float haloD = max(r - 1.0, 0.0) / max(uData[21].x, 0.001);
  float haloA = sat((uData[20].x + uData[23].y * level) * exp(-3.0 * haloD * haloD));
  under = vec4(uData[20].yzw * haloA, haloA);
  }
  if ((mod(floor(uData[3].w / 128.0), 2.0) > 0.5)) {
  float shadow = uData[21].y;
  if (shadow > 0.0) {
    vec2 s = (face - vec2(0.0, -1.0)) / vec2(0.8, 0.15);
    vec2 k = (face - vec2(0.0, -1.0)) / vec2(0.32, 0.06);
    vec4 floorC = vec4(vec3(uData[21].z, uData[21].w, uData[22].x), 1.0) * sat(shadow * exp(-2.5 * dot(s, s)));
    floorC = over(floorC, vec3(uData[7].w, uData[8].x, uData[8].y) * vec3(uData[5].z, uData[5].w, uData[6].x), sat(uData[22].y * exp(-2.5 * dot(k, k))));
    under += floorC * (1.0 - under.a);
  }
  }
  vec4 bg = uData[49 + 1];
  return under + vec4(bg.rgb * bg.a, bg.a) * (1.0 - under.a);
}

// The orb at frag, in the canvas's own units, y up from the bottom edge. Premultiplied.
vec4 orb(constant float4* uData, vec2 frag) {
  vec4 head = uData[0];
  vec4 clock = uData[1];
  vec4 m = uData[2];
  float level = head.z;
  if (uData[49].y > 0.5) return weatherView(uData, frag,head,clock);
  float wobble = uData[4].y + uData[24].y * level;
  float breathe = 1.0;
  if (wobble > 0.0) breathe -= wobble * (0.5 + 0.5 * sin(clock.x * 2.1));
  float halo = max(0.0, uData[20].x + uData[23].y * level);
  float glowBounds = halo > 0.0009765625 ? 1.0 + uData[21].x * sqrt(log(halo * 1024.0) / 3.0) : 1.0;
  float shade = uData[21].y;
  float shadowBounds = shade > 0.0009765625 ? sqrt(log(shade * 1024.0) / 2.5) : 0.0;
  float caustic = uData[22].y;
  float focusBounds = shade > 0.0 && caustic > 0.0009765625 ? sqrt(log(caustic * 1024.0) / 2.5) : 0.0;
  float side = max(1.0, max(glowBounds, max(shadowBounds * 0.8, focusBounds * 0.32)));
  float top = max(1.0, glowBounds);
  float bottom = max(top, 1.0 + max(shadowBounds * 0.15, focusBounds * 0.06));
  float radius = max(1.0, min(head.x / (2.0 * side), head.y / (top + bottom)) * uData[49].x * breathe);
  vec2 centre = 0.5 * head.xy + vec2(0.0, radius * (bottom - top) * 0.5);
  vec2 face = (frag - centre) / radius;
  float r = length(face);
  // One device pixel on the face, also where the canvas's units are points.
  float px = 1.0 / (radius * head.w);
  float coverage = cover(r - 1.0, px);

  vec4 under = outside(uData, face, r, level);
  if (coverage <= 0.0) return under;

  // The anti-aliased fringe just outside the rim samples the glass at the rim.
  vec2 f = r > 0.9999 ? face * (0.9999 / r) : face;
  float rr = min(r, 0.9999);

  // The inside, sampled from one place so a compiler that inlines it does so once: once, or once
  // a channel with dispersion bending each a little differently, and once more through the lens
  // of the drop this point sits in, if it sits in one.
  vec4 marks = vec4(0.0, 0.0, 1.0, 1.0);
  vec4 drop = vec4(0.0);
  if ((mod(floor(uData[3].w / 1.0), 2.0) > 0.5) || (mod(floor(uData[3].w / 2.0), 2.0) > 0.5) || (mod(floor(uData[49].z / 128.0), 2.0) > 0.5)) { drop = rainScan(uData, f, px, clock, marks); }
  // Fog blurs what is behind it, except where running drops have wiped it away.
  float fog = 0.0;
  if ((mod(floor(uData[3].w / 4.0), 2.0) > 0.5)) { fog = fogAt(uData, f, level, clock) * (1.0 - marks.x); }
  vec2 look = vec2(0.0);
  if (drop.w > 0.0) {
    look = dropLook(uData, vec3(drop.xy, abs(drop.z)), (f - drop.xy) / abs(drop.z));
    float lookR = length(look);
    if (lookR > 0.98) look *= 0.98 / lookR;
  }
  float blur = uData[5].y * 0.12 + fog * 0.16;
  float spread = uData[5].x * 0.06;
  int channels = spread > 0.0 ? 3 : 1;
  vec3 col = vec3(0.0);
  vec3 seen = vec3(0.0);
  for (int k = 0; k < 4; k++) {
    bool lens = k == 3;
    if (lens && drop.w <= 0.0) break;
    if (!lens && k >= channels) continue;
    vec3 got = insideAt(
      uData, lens ? look : f,
      lens ? px / abs(drop.z) * uData[16].x : px,
      level, clock, m,
      lens || channels == 1 ? 1.0 : 1.0 + spread * float(k - 1),
      lens ? 0.0 : blur
    );
    if (lens) seen = got * 1.06 + 0.03;
    else if (channels == 1) col = got;
    else if (k == 0) col.r = got.r;
    else if (k == 1) col.g = got.g;
    else col.b = got.b;
  }
  // Tinted glass: the middle, where it is thickest, takes the most of its colour.
  col *= pow(max(vec3(uData[5].z, uData[5].w, uData[6].x), vec3(0.0001)), vec3(0.5 + sqrt(1.0 - rr * rr)));
  col += (hash2(floor(frag * head.w)) - 0.5) * 0.08 * uData[5].y;
  col *= 1.0 + uData[23].x * level;
  // Sunshine warms what it falls through.
  if ((mod(floor(uData[3].w / 8.0), 2.0) > 0.5)) {
  col *= mix(vec3(1.0), vec3(uData[18].z, uData[18].w, uData[19].x) * 1.15, sat(uData[18].y + uData[24].x * level) * 0.18);
  }
  float opacity = uData[6].y;
  vec4 c = vec4(col * opacity, opacity);
  c = over(c, uData[9].xyz, uData[8].w * sat((r - 0.72) / 0.28));
  if ((mod(floor(uData[3].w / 4.0), 2.0) > 0.5)) { c = fogOver(uData, c, f, fog, px); }
  if ((mod(floor(uData[3].w / 1.0), 2.0) > 0.5) || (mod(floor(uData[3].w / 2.0), 2.0) > 0.5) || (mod(floor(uData[49].z / 128.0), 2.0) > 0.5)) { c = rain(uData, c, f, px, drop, seen, marks); }
  if ((mod(floor(uData[3].w / 16.0), 2.0) > 0.5)) { if (!((mod(floor(uData[3].w / 1.0), 2.0) > 0.5) || (mod(floor(uData[3].w / 2.0), 2.0) > 0.5) || (mod(floor(uData[49].z / 128.0), 2.0) > 0.5))) c = rain(uData, c, f, px, drop, seen, marks); }
  if ((mod(floor(uData[3].w / 8.0), 2.0) > 0.5)) { c = sunny(uData, c, f, px, level, drop); }
  if (((mod(floor(uData[3].w / 32.0), 2.0) > 0.5)) && (uData[6].z > 0.0)) { c = mirror(uData, c, f, uData[5].y * 0.12, clock); }
  c = glass(uData, c, f, r, px);
  if (((mod(floor(uData[49].z / 8.0), 2.0) > 0.5)) && (uData[31].x > 0.0)) { c = weatherLightning(uData, c,f,px,clock); }
  if (((mod(floor(uData[49].z / 16.0), 2.0) > 0.5)) && (uData[31].z > 0.0)) { c = frostWeather(uData, c,f,px,clock.x); }
  if (((mod(floor(uData[49].z / 64.0), 2.0) > 0.5)) && (uData[31].w > 0.0)) { c = airborneWeather(uData, c,f,px,clock.x); }
  if ((mod(floor(uData[3].w / 131072.0), 2.0) > 0.5)) { c = snowOver(uData, c, f, px, level); }

  if ((mod(floor(uData[3].w / 1024.0), 2.0) > 0.5)) {
  float luma = dot(c.rgb, vec3(0.2126, 0.7152, 0.0722));
  c.rgb = clamp(mix(vec3(luma), c.rgb, uData[22].z) * uData[22].w, vec3(0.0), vec3(c.a));
  }
  c.rgb = clamp(c.rgb, vec3(0.0), vec3(c.a));
  return c * coverage + under * (1.0 - c.a * coverage);
}

struct OrbVertexOut {
  float4 position [[position]];
};

// One triangle that covers the drawable, from the vertex id alone.
vertex OrbVertexOut orbVertex(uint id [[vertex_id]]) {
  float2 p = float2(float((id << 1) & 2), float(id & 2));
  OrbVertexOut out;
  out.position = float4(p * 2.0 - 1.0, 0.0, 1.0);
  return out;
}

// Metal's origin is the top-left corner, so turn y back up before drawing.
fragment float4 orbFragment(OrbVertexOut in [[stage_in]], constant float4* uData [[buffer(0)]]) {
  return orb(uData, float2(in.position.x, uData[0].y - in.position.y));
}
"""#,
  "media": #"""
#include <metal_stdlib>
using namespace metal;
typedef float2 vec2;
typedef float3 vec3;
typedef float4 vec4;
typedef float2x2 mat2;
typedef float3x3 mat3;
typedef float4x4 mat4;
typedef int2 ivec2;
typedef int3 ivec3;
typedef int4 ivec4;
inline float mod(float x, float y) { return x - y * floor(x / y); }
inline float2 mod(float2 x, float y) { return x - y * floor(x / y); }
inline float3 mod(float3 x, float y) { return x - y * floor(x / y); }
inline float4 mod(float4 x, float y) { return x - y * floor(x / y); }
inline float2 mod(float2 x, float2 y) { return x - y * floor(x / y); }
inline float3 mod(float3 x, float3 y) { return x - y * floor(x / y); }
inline float4 mod(float4 x, float4 y) { return x - y * floor(x / y); }
inline float atan(float y, float x) { return atan2(y, x); }
inline float inversesqrt(float x) { return rsqrt(x); }

float4 sampleMedia(constant float4* uData, texture2d<float> uMedia, float2 uv, float lod) {
  constexpr sampler linear(filter::linear, mip_filter::linear, address::clamp_to_edge);
  return uMedia.sample(linear, uv, level(lod));
}

float sat(float x) { return clamp(x, 0.0, 1.0); }

// Coverage of a shape whose signed distance is d, softened over w either side of its edge.
float cover(float d, float w) { return 1.0 - smoothstep(-w, w, d); }

// v folded into [lo, hi), for things that drift off one side and come back on the other.


float boxSdf(vec2 p, vec2 extent) {
  vec2 q = abs(p) - extent;
  return length(max(q, vec2(0.0))) + min(max(q.x, q.y), 0.0);
}



// A hash of a point without sin, which stays steady on mobile GPUs.
float hash2(vec2 p) {
  vec3 q = fract(vec3(p.x, p.y, p.x) * 0.1031);
  q += dot(q, vec3(q.y, q.z, q.x) + 33.33);
  return fract((q.x + q.y) * q.z);
}

// Smooth value noise, 0 to 1.
float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  float a = hash2(i);
  float b = hash2(i + vec2(1.0, 0.0));
  float c = hash2(i + vec2(0.0, 1.0));
  float d = hash2(i + vec2(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

// Value noise summed over octaves, each twice as fine and turned. octaves is at most 7.
float fbm(vec2 p, int octaves) {
  float sum = 0.0;
  float amp = 0.5;
  for (int i = 0; i < 7; i++) {
    if (i >= octaves) break;
    sum += amp * vnoise(p);
    p = vec2(1.6 * p.x - 1.2 * p.y, 1.2 * p.x + 1.6 * p.y);
    amp *= 0.5;
  }
  return sum;
}

vec2 rotate2(vec2 p, float a) {
  float c = cos(a);
  float s = sin(a);
  return vec2(c * p.x - s * p.y, s * p.x + c * p.y);
}

// Premultiplied c with x laid over it at opacity a.
vec4 over(vec4 c, vec3 x, float a) { return vec4(mix(c.rgb, x, a), mix(c.a, 1.0, a)); }

// Where a scene point d from the centre lands on the face (see lens.ts).


// The glass, inverted: the scene point that shows at this point of the face, and how much the
// glass magnifies there (scene units per face unit is its reciprocal).
vec3 unbend(vec2 face, float bend) {
  if (bend <= 0.00001) return vec3(face, 1.0);
  float rho = length(face);
  float d = min(rho, 1.0);
  for (int i = 0; i < 5; i++) {
    float f = (1.0 - bend) * d + bend * sin(d * 1.5707963) - rho;
    float df = (1.0 - bend) + bend * 1.5707963 * cos(d * 1.5707963);
    d = clamp(d - f / max(df, 0.001), 0.0, 1.0);
  }
  float gain = max((1.0 - bend) + bend * 1.5707963 * cos(d * 1.5707963), 0.001);
  vec2 s = rho > 0.00001 ? face * (d / rho) : face / ((1.0 - bend) + bend * 1.5707963);
  return vec3(s, gain);
}

// Where the light is: the direction the view reflects to off the glass at the light's highlight.
vec3 lightDir(constant float4* uData, texture2d<float> uMedia) {
  vec2 at = vec2(uData[7].y, uData[7].z);
  float radius = length(at);
  vec2 direction = radius > 0.00001 ? at / radius : vec2(0.0, 1.0);
  // Extend the source beyond the glass without a zero half-vector at the rim. The elevation
  // offset changes incidence independently of the source's visible glare position.
  float r = min(radius, 0.999);
  float z = sqrt(1.0 - r * r);
  vec3 natural = vec3(2.0 * z * r * direction, 1.0 - 2.0 * r * r);
  if (abs(uData[24].w) < 0.00001) return natural;
  float elevation = clamp(asin(clamp(natural.z, -1.0, 1.0)) + uData[24].w * 0.01745329,
    -1.526326, 1.5707963);
  return normalize(vec3(direction * cos(elevation), sin(elevation)));
}

// The light's specular point on the sphere, distinct from its source position outside the orb.
vec2 lightSpot(constant float4* uData, texture2d<float> uMedia) {
  return normalize(lightDir(uData, uMedia) + vec3(0.0, 0.0, 1.0)).xy;
}

// How bright the light's softbox is along d, 0 to 1, softened by blur.
float softbox(constant float4* uData, texture2d<float> uMedia, vec3 d, float blur) {
  float size = 0.16 * uData[8].z + blur;
  float a = acos(clamp(dot(d, lightDir(uData, uMedia)), -1.0, 1.0));
  return 1.0 - smoothstep(size * 0.55, size, a);
}

// The room round the orb, by direction (y up, z toward the viewer): a sweep of wall over a floor,
// with tall softboxes round it, which show the room turning as it turns. The eye looks a little
// down on the orb, so behind it is floor and the horizon curves through the glass. spin turns the
// room (radians) and blur softens it.
vec3 room(constant float4* uData, texture2d<float> uMedia, vec3 d, float blur, float spin) {
  vec3 t = vec3(d.x, d.y * 0.9689 + d.z * 0.2474, d.z * 0.9689 - d.y * 0.2474);
  vec2 xz = rotate2(vec2(t.x, t.z), spin);
  vec3 q = vec3(xz.x, t.y, xz.y);
  vec3 col = mix(vec3(uData[12].w, uData[13].x, uData[13].y), uData[12].xyz, smoothstep(0.0, 0.75 + blur, q.y));
  col = mix(col, vec3(uData[13].z, uData[13].w, uData[14].x), smoothstep(-0.015 - blur, 0.45 + blur, -q.y));
  col *= 1.0 - 0.3 * smoothstep(0.45, 1.0, -q.y);
  float around = atan2(q.x, 0.000001 - q.z);
  float cell = abs(around - 2.0943951 * floor(around / 2.0943951 + 0.5));
  float panel = (1.0 - smoothstep(0.26, 0.32 + blur, cell))
    * smoothstep(0.04, 0.09 + blur, q.y) * (1.0 - smoothstep(0.5, 0.56 + blur, q.y));
  return mix(col, mix(uData[12].xyz, vec3(1.0), 0.85), panel);
}

// Which way a ray along -z leaves a solid ball of glass through this point of its face: bent in
// at the front and out at the back, so what is behind the ball shows upside down.
vec3 throughBall(vec2 face, float ior) {
  vec3 p = vec3(face, sqrt(max(0.0, 1.0 - dot(face, face))));
  vec3 d = refract(vec3(0.0, 0.0, -1.0), p, 1.0 / ior);
  vec3 q = p - 2.0 * dot(p, d) * d;
  vec3 o = refract(d, -q, ior);
  return dot(o, o) > 0.5 ? o : reflect(d, -q);
}

float weatherWind(constant float4* uData, texture2d<float> uMedia, float time) {
  float envelope = 0.5 + 0.28 * sin(time * 0.73) + 0.22 * sin(time * 1.37 + 1.9);
  return uData[29].z + max(0.0, uData[29].w - uData[29].z) * envelope * uData[30].x;
}
float cloudDensity(constant float4* uData, texture2d<float> uMedia, vec2 p, float time) {
  float motion = 1.0 - uData[30].y;
  vec2 travel = vec2(uData[2].w + uData[2].z * 0.002, time * 0.002) * motion;
  vec2 q = (p - vec2(0.0, uData[32].w)) * (2.0 / uData[32].z) - travel;
  float broad = fbm(q, 5);
  float wisps = fbm(q * 2.7 + vec2(13.2, 9.6), 3);
  float threshold = mix(0.92, 0.13, uData[32].x);
  return smoothstep(threshold - 0.12, threshold + 0.16, broad + wisps * 0.16);
}
// One pulse per seeded interval; never a rapid sequence of strobe flashes.
vec3 stormEvent(constant float4* uData, texture2d<float> uMedia, float time) {
  float interval = 1.0 / max(0.01, uData[36].w);
  float event = floor(time / interval);
  float seed = hash2(vec2(event, 71.3));
  float start = interval * (0.2 + seed * 0.45);
  float age = mod(time, interval) - start;
  float pulse = age >= 0.0 ? exp(-age * 5.5) * smoothstep(0.0, 0.035, age) : 0.0;
  pulse *= step(seed, uData[36].z) * (1.0 - uData[30].y);
  return vec3(pulse, event, age);
}
// Connected, irregular channels with narrower forks and a separate scattered-light halo.
// Visual reference: Kim & Lin, Physically Based Animation and Rendering of Lightning (2004).
// This bounded analytic tree avoids running their dielectric-breakdown simulation per pixel.
vec2 boltVertex(float event, float n) {
  float start = hash2(vec2(event,3.1)) * 1.3 - 0.65;
  float drift = (hash2(vec2(event,19.8))-0.5) * 0.55;
  float broad = (vnoise(vec2(n*0.27,event+9.7))-0.5) * 0.42;
  float kink = (hash2(vec2(event+4.6,n+7.3))-0.5) * 0.13;
  float stepY = n + (hash2(vec2(event+2.8,n+11.9))-0.5) * 0.5;
  return vec2(start + drift*n/24.0 + broad + kink,1.18-stepY*0.1);
}
vec2 boltSegment(vec2 p, vec2 a, vec2 b, float width, float px) {
  vec2 segment = b-a;
  float along = sat(dot(p-a,segment)/max(dot(segment,segment),0.000001));
  float d = length(p-a-segment*along);
  return vec2(cover(d-width,px*0.8),exp(-d/max(width*5.0,px*1.8)));
}
vec2 forkVertex(vec2 root, vec2 tip, float seed, float n) {
  float t = n/8.0;
  vec2 direction = tip-root;
  vec2 normal = vec2(-direction.y,direction.x);
  float kink = (hash2(vec2(seed,n+17.7))-0.5) * 0.22 * sin(t*3.141593);
  return mix(root,tip,t) + normal*kink;
}
vec2 boltFork(vec2 p, vec2 root, vec2 tip, float seed, float width, float px) {
  vec2 low = min(root,tip)-vec2(0.14), high = max(root,tip)+vec2(0.14);
  if (p.x < low.x || p.x > high.x || p.y < low.y || p.y > high.y) return vec2(0.0);
  vec2 energy = vec2(0.0), previous = root;
  for (int k = 0; k < 8; k++) {
    float n = float(k)+1.0;
    vec2 next = forkVertex(root,tip,seed,n);
    float taper = mix(1.0,0.38,n/8.0);
    energy = max(energy,boltSegment(p,previous,next,width*taper,px)*mix(1.0,0.65,n/8.0));
    previous = next;
  }
  return energy;
}
vec2 lightningChannels(vec2 p, float event, float branching, float px) {
  float width = max(px*0.6,0.0022);
  vec2 energy = vec2(0.0), previous = boltVertex(event,0.0);
  for (int k = 0; k < 24; k++) {
    float n = float(k);
    vec2 next = boltVertex(event,n+1.0);
    energy = max(energy,boltSegment(p,previous,next,width*mix(1.0,0.72,n/24.0),px));
    if (k > 0 && k < 21 && mod(n,4.0) == 2.0 && branching > 0.0) {
      float seed = hash2(vec2(event+23.6,n+13.1));
      float visibility = smoothstep(seed*0.65,seed*0.65+0.3,branching);
      if (visibility > 0.0) {
        float side = hash2(vec2(event+41.2,n)) < 0.5 ? -1.0 : 1.0;
        vec2 root = mix(previous,next,0.25+seed*0.5);
        vec2 tip = root + vec2(side*(0.22+seed*0.52),-(0.24+hash2(vec2(n,event+6.7))*0.55));
        vec2 fork = boltFork(p,root,tip,event*31.7+n,width*mix(0.45,0.9,branching),px);
        float brightness = visibility*mix(0.65,1.25,branching);
        energy = max(energy,fork*brightness*vec2(1.0,0.85));
        vec2 twigRoot = forkVertex(root,tip,event*31.7+n,4.0);
        vec2 twigTip = twigRoot+vec2(-side*(0.1+seed*0.16),-(0.15+seed*0.18));
        vec2 twig = boltFork(p,twigRoot,twigTip,event*17.3+n+5.2,width*0.45,px);
        energy = max(energy,twig*brightness*branching*vec2(0.7,0.55));
        if (branching > 0.7) {
          vec2 secondRoot = forkVertex(root,tip,event*31.7+n,6.0);
          vec2 secondTip = secondRoot+vec2(side*(0.12+seed*0.16),-(0.12+seed*0.22));
          vec2 second = boltFork(p,secondRoot,secondTip,event*13.1+n+7.8,width*0.38,px);
          energy = max(energy,second*brightness*smoothstep(0.7,1.0,branching)*vec2(0.65,0.5));
        }
      }
    }
    previous = next;
  }
  return energy;
}
vec4 weatherSky(constant float4* uData, texture2d<float> uMedia, vec4 c, vec2 p, float px, vec4 clock) {
  float daylight = 1.0;
  if (((mod(floor(uData[45].z / 2.0), 2.0) > 0.5)) && (uData[30].z > 0.0)) {
  if (uData[32].x > 0.0) {
    float density = cloudDensity(uData, uMedia, p, clock.x);
    float lit = cloudDensity(uData, uMedia, p + lightDir(uData, uMedia).xy * 0.085, clock.x);
    float optical = density * (1.0 + 4.0 * uData[32].y);
    float opacity = 1.0 - exp(-optical);
    float silver = sat((density - lit) * 5.0);
    vec3 cloud = mix(uData[34].xyz, uData[33].yzw, 0.42 + silver * 0.45 + (1.0-density)*0.2);
    cloud *= mix(0.22, 1.0, daylight);
    c = over(c, cloud, opacity);
  }
  }
  if (((mod(floor(uData[45].z / 4.0), 2.0) > 0.5)) && (uData[30].w > 0.0)) {
  if (uData[34].w > 0.0) {
    float depth = uData[35].y * (0.5 + 0.5 * smoothstep(-1.0, 0.8, -p.y));
    float extinction = 3.912 / max(50.0, uData[35].x);
    float mottled = 0.85 + 0.15 * fbm(p * 2.0 + vec2(clock.x * uData[35].z, 0.0) * (1.0-uData[30].y), 3);
    float opacity = (1.0 - exp(-extinction * depth)) * uData[34].w * mottled;
    c = over(c, vec3(uData[35].w, uData[36].x, uData[36].y) * mix(0.25, 1.0, daylight), opacity);
  }
  }
  return c;
}
vec4 weatherLightning(constant float4* uData, texture2d<float> uMedia, vec4 c, vec2 p, float px, vec4 clock) {
  if (((mod(floor(uData[45].z / 8.0), 2.0) > 0.5)) && (uData[31].x > 0.0)) {
  vec3 event = stormEvent(uData, uMedia, clock.x);
  float illumination = exp(-length(p - vec2(hash2(vec2(event.y,3.1))*1.5-0.75,0.8)) * 0.9);
  c = over(c, vec3(uData[37].z, uData[37].w, uData[38].x), event.x * illumination * 0.32);
  if (uData[37].x > 0.0 && event.x > 0.01) {
    vec2 bolt = lightningChannels(p,event.y,uData[37].y,px);
    float strength = event.x * uData[37].x;
    c = over(c, vec3(uData[37].z, uData[37].w, uData[38].x), sat(bolt.y*strength*0.45));
    c = over(c, mix(vec3(uData[37].z, uData[37].w, uData[38].x),vec3(1.0),0.88), sat(bolt.x*strength*1.4));
  }
  }
  return c;
}
vec4 airborneWeather(constant float4* uData, texture2d<float> uMedia, vec4 c, vec2 p, float px, float time) {
  float rain = uData[28].z * uData[15].x;
  float snow = uData[28].w * sat(uData[25].x + uData[27].w * uData[0].z) * uData[25].y;
  float hail = uData[31].y * uData[38].y * uData[38].z;
  if (rain + snow + hail <= 0.0) return c;
  float strength = weatherWind(uData, uMedia, time);
  float movement = 1.0 - uData[30].y;
  // Separate streams keep mixed precipitation and individual incoming angles independent.
  // Empty streams skip their grids entirely.
  for (int kind = 0; kind < 3; kind++) {
    float intensity = kind == 0 ? rain : (kind == 1 ? snow : hail);
    if (intensity <= 0.0) continue;
    float offset = kind == 0 ? uData[24].z : (kind == 1 ? uData[25].w : 0.0);
    float angle = clamp(uData[28].x + offset, -80.0, 80.0) * 0.01745329;
    vec2 down = vec2(sin(angle), -cos(angle));
    float pace = kind == 0 ? 1.25 : (kind == 1 ? 0.22 * uData[26].x : 1.8);
    for (int layer = 0; layer < 3; layer++) {
      float z = (float(layer) + 0.4) / 3.0;
      float depth = mix(1.0, z, uData[42].x);
      float grid = 7.0 + float(layer) * 6.0;
      vec2 shift = down * (time * pace * (0.65 + depth * 0.45) + uData[2].z * 0.035) * movement;
      shift.x += sin(time*0.7 + z*5.0) * uData[30].x * strength * (kind == 1 ? 0.008 : 0.002) * movement;
      vec2 q = (p - shift) * grid;
      vec2 cell = floor(q);
      for (int neighbor = 0; neighbor < 9; neighbor++) {
        vec2 tile = cell + vec2(float(neighbor - 3*(neighbor/3)) - 1.0, float(neighbor/3) - 1.0);
        vec2 key = tile + vec2(z*79.3 + float(kind)*117.1, z*21.1 + float(kind)*31.7);
        float seed = hash2(key);
        if (seed > intensity * 0.8) continue;
        vec2 at = tile + vec2(hash2(key+vec2(13.1,z)), hash2(key+vec2(z,9.7)));
        vec2 rel = (q-at) / grid;
        float alpha = 0.0;
        vec3 color = uData[27].xyz;
        if (kind == 0) {
          vec2 line = down * (0.025 + depth * 0.09) * uData[28].y;
          float h = sat(dot(rel,line) / max(dot(line,line),0.000001));
          float d = length(rel-line*h);
          alpha = cover(d - (0.00065+depth*0.0015)*uData[28].y,px) * 0.28 * depth;
          color = mix(uData[27].xyz, vec3(0.72,0.82,0.9),0.75);
        } else if (kind == 1) {
          float radius = (0.004+depth*0.009) * uData[26].y * (0.7 + seed*0.5);
          vec2 flake = rotate2(rel / radius, seed*6.283 + time*(seed-0.5)*movement);
          float a = atan2(flake.y,flake.x);
          float branches = 0.6 + 0.25*cos(a*6.0) + 0.08*cos(a*12.0+seed*8.0);
          alpha = cover(length(flake)-branches,px/radius) * 0.7 * depth;
        } else {
          alpha = cover(length(rel)-(0.003+depth*0.007)*uData[38].w,px) * 0.85 * depth;
          color = vec3(uData[39].z, uData[39].w, uData[40].x);
        }
        c = over(c,color,alpha*uData[41].w);
      }
    }
  }
  return c;
}
vec4 frostWeather(constant float4* uData, texture2d<float> uMedia, vec4 c, vec2 p, float px, float time) {
  float amount = uData[45].w;
  if (amount <= 0.0) return c;
  float patches = fbm(p*5.0,5);
  float edge = pow(sat(dot(p,p)),2.0);
  float glaze = smoothstep(0.9-amount*0.85,1.05-amount*0.65,patches+edge*0.4);
  float angle = atan2(p.y,p.x);
  float crystals = pow(max(0.0,sin(angle*18.0+fbm(p*9.0,3)*6.0)),12.0) * edge;
  float scatter = mix(0.15,0.75,uData[40].z);
  float grain = vnoise(p*120.0) * (1.0-smoothstep(0.003,0.012,px));
  c = over(c,uData[41].xyz,glaze*(scatter+grain*0.12));
  c.rgb += uData[41].xyz * crystals * glaze * 0.09;
  return c;
}

vec4 orbContents(constant float4* uData, texture2d<float> uMedia, vec2 s, vec2 face, float w, float k, float blur, float level, vec4 clock, vec4 m) {
  vec4 media = uData[3];
  if (media.z < 0.5) return vec4(0.0);
  float zoom = uData[43].x * (1.0 + 0.25 * uData[44].y * level);
  vec2 p = rotate2(s - vec2(uData[43].y, uData[43].z), -(uData[43].w + m.x) * 0.01745329) / zoom;
  // The picture's half-size in glass units: covering fits its shorter side across the glass,
  // containing its longer one.
  float aspect = media.x / max(media.y, 1.0);
  bool contain = uData[1304].x > 0.5;
  vec2 extent = (aspect > 1.0) != contain ? vec2(aspect, 1.0) : vec2(1.0, 1.0 / aspect);
  float within = cover(boxSdf(p, extent), w / zoom);
  if (within <= 0.0) return vec4(0.0);
  vec2 uv = vec2(0.5 + 0.5 * p.x / extent.x, 0.5 - 0.5 * p.y / extent.y);
  // How many texels one pixel spans here, frosting included, picks the mip level.
  float texels = (1.5 * w + blur) / zoom * 0.5 * media.y / extent.y;
  return sampleMedia(uData, uMedia, clamp(uv, vec2(0.0), vec2(1.0)), log2(max(texels, 1.0))) * within;
}

// What shows through the glass at a point of the face: the contents, bent by the glass, over the
// room seen through the ball. scale bends one channel a little more or less, for dispersion; blur
// is the frosting on the face.
vec3 insideAt(constant float4* uData, texture2d<float> uMedia, vec2 face, float px, float level, vec4 clock, vec4 m, float scale, float blur) {
  vec3 un = unbend(face, uData[4].z * scale);
  vec4 c = orbContents(uData, uMedia, un.xy, face, 0.75 * px / un.z, 1.0 / un.z, blur / un.z, level, clock, m);
  c = weatherSky(uData, uMedia, c, un.xy, px, clock);
  if (c.a >= 0.999) return c.rgb;
  vec3 behind = throughBall(face, 1.0 + (uData[4].w - 1.0) * scale);
  return c.rgb + room(uData, uMedia, behind, blur, clock.z * 0.01745329) * (1.0 - c.a);
}

// Where a drop looks: a bead of water is a lens, gathering a wide patch of the view behind it,
// upside down. drop is its centre and radius; q is this point in the drop, -1 to 1.
vec2 dropLook(constant float4* uData, texture2d<float> uMedia, vec3 drop, vec2 q) {
  return drop.xy - q * uData[16].x;
}

// The drop's colour, from the glass under it (col) and what its lens gathers (seen).
vec3 dropView(constant float4* uData, texture2d<float> uMedia, vec3 col, vec3 seen, vec3 drop, vec2 q) {
  return mix(col, seen, 0.8);
}

vec4 weatherView(constant float4* uData, texture2d<float> uMedia, vec2 frag, vec4 head, vec4 clock) {
  float unit = max(1.0,head.y*0.5);
  vec2 p = (frag-head.xy*0.5)/unit;
  float px = 1.0/(unit*head.w);
  vec4 c = uData[45].y < 1.5 ? vec4(mix(vec3(uData[12].w, uData[13].x, uData[13].y),uData[12].xyz,sat(p.y*0.5+0.5)),1.0) : vec4(0.0);
  if (uData[45].y < 1.5) {
    vec4 contents = orbContents(uData, uMedia, p,p,px,1.0,0.0,head.z,clock,uData[2]);
    c = contents + c * (1.0-contents.a);
    c = weatherSky(uData, uMedia, c,p,px,clock);
    if (((mod(floor(uData[45].z / 8.0), 2.0) > 0.5)) && (uData[31].x > 0.0)) { c = weatherLightning(uData, uMedia, c,p,px,clock); }
  }
  else {
    if (((mod(floor(uData[45].z / 4.0), 2.0) > 0.5)) && (uData[30].w > 0.0)) {
    float opacity = (1.0-exp(-3.912*uData[35].y/max(50.0,uData[35].x)))*uData[34].w;
    c = over(c,vec3(uData[35].w, uData[36].x, uData[36].y),opacity);
    }
    if (((mod(floor(uData[45].z / 8.0), 2.0) > 0.5)) && (uData[31].x > 0.0)) {
    c = weatherLightning(uData, uMedia, c,p,px,clock);
    }
  }
  if (((mod(floor(uData[45].z / 64.0), 2.0) > 0.5)) && (uData[31].w > 0.0)) { c = airborneWeather(uData, uMedia, c,p,px,clock.x); }
  return c;
}

// Rain on the inside of the glass. Drops sit where they landed. Running drops stick and slip down
// it, leaving a streak of water that beads up behind them, and a path clear of fog and mist.
// Every drop casts a shadow; the water a point sits in (drops rarely overlap, so one is enough) is
// a lens.

// A drop as the glass shows it: smaller toward the rim, where the glass curves away, and fading
// there, so one running off the bottom and back on at the top never pops. Centre, radius, alpha.


// Water joins only at contact, matching the simulation. A small smoothing zone rounds the neck
// while the smaller drop retracts into the larger one.

// Keep the two drops face sits deepest in, by how deep (k, |q|): hit and next, how deep each in
// near. The first counts out to where merging or its edge's anti-aliasing reaches, the second out
// to where merging does.
void consider(vec4 d, float k, float reach, thread vec4& hit, thread vec4& next, thread vec2& near) {
  if (k < near.x && k < reach) {
    next = hit;
    near.y = near.x;
    hit = d;
    near.x = k;
  } else if (k < near.y && k < 1.03) {
    next = d;
    near.y = k;
  }
}

// The water face is in, from the two drops it sits deepest in (see consider): as a drop, with its
// alpha the share of face it covers. Where two touch, they are one: each a dome of water, the two
// joined by a smooth maximum, so they fill in where they meet, and the slope turns from the one to
// the other.
vec4 water(vec2 face, float px, vec4 a, vec4 b, vec2 near) {
  if (a.w <= 0.0) return vec4(0.0);
  float ra = abs(a.z);
  vec2 qa = (face - a.xy) / ra;
  if (near.y >= 1.03 || b.w <= 0.0) return vec4(a.xyz, a.w * cover((length(qa) - 1.0) * ra, px));
  float rb = abs(b.z);
  vec2 qb = (face - b.xy) / rb;
  float ea = 0.5 * ra * (1.0 - dot(qa, qa));
  float eb = 0.5 * rb * (1.0 - dot(qb, qb));
  float soft = 0.05 * min(ra, rb);
  float l = sat(0.5 + 0.5 * (ea - eb) / soft);
  float e = mix(eb, ea, l) + soft * l * (1.0 - l);
  vec2 q = mix(qb, qa, l);
  float s = mix(rb, ra, l);
  float k = sqrt(max(0.0, 1.0 - 2.0 * e / s));
  float film = l < 0.5 ? b.z : a.z;
  return vec4(face - q * s, film < 0.0 ? -s : s, mix(b.w, a.w, l) * cover((k - 1.0) * s, px));
}

// Surface discs share their geometry with the simulation's contact test.
vec2 pathPoint(float code) {
  float a = floor(code / 4096.0);
  return vec2(a, code - a * 4096.0) / 4095.0 * 2.4 - 1.2;
}
// Each lobe has 12 bits of direction and 12 of deformation, with no coarse shape steps.
vec3 dropShape(float code) {
  float drive = floor(code / 4096.0) / 4095.0;
  if (drive <= 0.0) return vec3(0.0, -1.0, 0.0);
  float angle = (code - floor(code / 4096.0) * 4096.0) / 4095.0 * 6.28318530718 - 3.14159265359;
  return vec3(cos(angle), sin(angle), drive);
}

// A moving footprint stretches with velocity and narrows toward its trailing contact line.
// The analytic derivative includes that taper, so the outline and optical slope stay consistent.
vec3 dropField(vec2 face, vec3 d, vec3 shape) {
  vec2 rel = face - d.xy;
  float radial = length(d.xy);
  vec2 axis = radial > 0.001 ? d.xy / radial : vec2(0.0, 1.0);
  float z = sqrt(max(0.025, 1.0 - dot(d.xy, d.xy)));
  vec2 tangent = rel + axis * dot(rel, axis) * (1.0 / z - 1.0);
  vec2 direction = shape.xy + axis * dot(shape.xy, axis) * (1.0 / z - 1.0);
  direction /= max(length(direction), 0.00001);
  vec2 side = vec2(-direction.y, direction.x);
  float along = dot(tangent, direction);
  float across = dot(tangent, side);
  float stretch = 1.0 + 0.32 * shape.z;
  float shifted = along + 0.06 * shape.z * d.z;
  float u = shifted / (d.z * stretch);
  float taper = 1.0 + 0.14 * shape.z * clamp(u, -1.0, 1.0);
  float taperSlope = abs(u) < 1.0 ? 0.14 * shape.z / (d.z * stretch) : 0.0;
  float qa = shifted / stretch;
  float qb = across * sqrt(stretch) / taper;
  float len = sqrt(qa * qa + qb * qb);
  float ga = (qa / stretch - qb * across * sqrt(stretch) * taperSlope / (taper * taper)) / max(len, 0.00001);
  float gb = qb * sqrt(stretch) / taper / max(len, 0.00001);
  vec2 grad = direction * ga + side * gb;
  grad += axis * dot(grad, axis) * (1.0 / z - 1.0);
  return vec3(len - d.z, grad);
}

// Contact tension reshapes a lobe toward the neck while its far contact line briefly stays
// on the glass. This tangent-plane warp preserves area, including the original moving shape.
// Transform its analytic gradient with the same warp so the entire optical surface responds.
vec3 contactField(vec2 face, vec3 d, vec3 shape, vec2 toward, float tension) {
  if (tension <= 0.0) return dropField(face, d, shape);
  float radial = length(d.xy);
  vec2 axis = radial > 0.001 ? d.xy / radial : vec2(0.0, 1.0);
  float z = sqrt(max(0.025, 1.0 - dot(d.xy, d.xy)));
  vec2 direction = toward + axis * dot(toward, axis) * (1.0 / z - 1.0);
  direction /= max(length(direction), 0.00001);
  vec2 side = vec2(-direction.y, direction.x);
  vec2 point = face - d.xy;
  point += axis * dot(point, axis) * (1.0 / z - 1.0);
  float stretch = 1.0 + 0.28 * tension;
  float offset = (stretch - 1.0) * d.z;
  vec2 mapped = direction * ((dot(point, direction) - offset) / stretch)
    + side * dot(point, side) * stretch;
  mapped += axis * dot(mapped, axis) * (z - 1.0);
  vec3 field = dropField(d.xy + mapped, d, shape);
  vec2 grad = field.yz;
  grad += axis * dot(grad, axis) * (z - 1.0);
  grad = direction * (dot(grad, direction) / stretch) + side * dot(grad, side) * stretch;
  grad += axis * dot(grad, axis) * (1.0 / z - 1.0);
  return vec3(field.x, grad);
}

// Height and gradient of the water cap above its footprint. Combining footprint distances
// alone leaves the small lobe's steep optical slope intact, even after it is inside the head.
// Combine these heights instead, so the advancing surface covers and relaxes that little bump.
vec3 dropCap(vec3 field, float radius) {
  float k = max(0.0, 1.0 + field.x / radius);
  return vec3(0.5 * radius * (1.0 - k * k), -field.yz * k);
}

// A contacting pair has one water height and one optical normal. The smooth maximum rounds
// its meniscus, and its derivative supplies the slope across both lobes and the connection.
void sphereWater(vec2 face, float px, vec4 a, vec4 b, float neck, vec2 codes,
                 thread vec4& liquid, thread float& deepest, thread float& shadow) {
  if (a.z <= 0.0 || a.w <= 0.0) return;
  vec2 reach = vec2(2.25 * a.z + neck + px);
  vec2 lo = a.xy - reach;
  vec2 hi = a.xy + reach;
  if (b.z > 0.0) {
    lo = min(lo, b.xy - vec2(2.25 * b.z + neck + px));
    hi = max(hi, b.xy + vec2(2.25 * b.z + neck + px));
  }
  // Include the small exterior shadow without evaluating distant footprints.
  if (face.x < lo.x - a.z || face.y < lo.y - a.z || face.x > hi.x + a.z || face.y > hi.y + a.z) return;
  vec3 shapeA = dropShape(codes.x);
  vec3 shapeB = dropShape(codes.y);
  vec3 field = dropField(face, a.xyz, shapeA);
  vec3 surface = dropCap(field, a.z);
  // Shadows follow the real footprint, rather than the virtual refraction centre. That centre
  // changes at every fragment and used to extend the shadow into a hard column below the water.
  float shadowDistance = dropField(face + vec2(0.0, 0.22 * a.z), a.xyz, shapeA).x;
  float shadowSize = a.z;
  float size = a.z;
  float alpha = a.w;
  if (b.z > 0.0) {
    vec2 toward = b.xy - a.xy;
    toward = length(toward) > 0.00001 ? toward / length(toward) : vec2(0.0, -1.0);
    float atContact = dropField(b.xy, a.xyz, shapeA).x;
    // Catch on the first visible touch, before volume begins draining. Let that strain relax
    // as the small lobe is enveloped; the smaller body supplies most of the shape response.
    float touching = 1.0 - smoothstep(0.0, 2.0 * px, atContact - b.z);
    float uncovered = smoothstep(-b.z, 0.0, atContact);
    float strain = (0.22 + 0.78 * smoothstep(0.08, 0.5, neck / b.z)) * touching * uncovered;
    float share = b.z * b.z / (a.z * a.z + b.z * b.z);
    float tensionA = strain * share;
    float tensionB = strain * (1.0 - share);
    field = contactField(face, a.xyz, shapeA, toward, tensionA);
    surface = dropCap(field, a.z);
    shadowDistance = contactField(face + vec2(0.0, 0.22 * a.z), a.xyz, shapeA, toward, tensionA).x;
    vec3 other = dropCap(contactField(face, b.xyz, shapeB, -toward, tensionB), b.z);
    float otherShadow = contactField(face + vec2(0.0, 0.22 * b.z), b.xyz, shapeB, -toward, tensionB).x;
    if (otherShadow < shadowDistance) { shadowDistance = otherShadow; shadowSize = b.z; }
    float soft = max(min(neck, b.z) * uncovered, 0.000001);
    float h = sat(0.5 + 0.5 * (surface.x - other.x) / soft);
    surface = vec3(mix(other.x, surface.x, h) + soft * h * (1.0 - h), mix(other.yz, surface.yz, h));
    size = mix(b.z, a.z, h);
    alpha = max(a.w, b.w);
    // A connection spans exposed water; it must not leave its own rounded endpoint at the
    // donor's old centre after the head has covered it. Limit it to the remaining lobe and
    // relax it away as that contact point is enveloped by the advancing footprint.
    float gap = contactField(b.xy, a.xyz, shapeA, toward, tensionA).x - b.z * (1.0 + 0.56 * tensionB);
    float exposed = smoothstep(-b.z, 0.0, gap);
    float bridgeRadius = min(neck, b.z) * exposed;
    if (bridgeRadius > 0.000001) {
      vec2 segment = b.xy - a.xy;
      float u = clamp(dot(face - a.xy, segment) / max(dot(segment, segment), 0.000001), 0.0, 1.0);
      vec3 bridge = dropField(face, vec3(a.xy + segment * u, bridgeRadius), vec3(0.0, -1.0, 0.0));
      if (u > 0.0 && u < 1.0) bridge.yz -= segment * dot(bridge.yz, segment) / max(dot(segment, segment), 0.000001);
      bridge = dropCap(bridge, bridgeRadius);
      float rounding = max(0.5 * bridgeRadius, 0.000001);
      float join = sat(0.5 + 0.5 * (surface.x - bridge.x) / rounding);
      surface = vec3(mix(bridge.x, surface.x, join) + rounding * join * (1.0 - join), mix(bridge.yz, surface.yz, join));
      size = mix(bridgeRadius, size, join);
    }
  }
  float radial = length(face);
  alpha *= 1.0 - smoothstep(0.97, 1.08, radial);
  float distance = b.z > 0.0 ? -surface.x : field.x;
  float edge = max(px, px * length(b.z > 0.0 ? surface.yz : field.yz));
  alpha *= sat(size / px);
  float coverage = alpha * cover(distance, edge);
  // One height gradient supplies every optical cue. A small lobe that the advancing cap has
  // enveloped no longer contributes a separate spherical highlight or a steep little rim.
  vec2 q = -surface.yz;
  // Project the tangent normal into the view. Screen-space distance derivatives grow toward
  // the rim; feeding them straight into refraction made the water look like a rigid sharp edge.
  vec2 axis = radial > 0.001 ? face / radial : vec2(0.0, 1.0);
  q += axis * dot(q, axis) * (max(0.025, 1.0 - dot(face, face)) - 1.0);
  q *= 0.8;
  vec4 lens = vec4(face - q * size, size, alpha);
  shadow *= 1.0 - 0.08 * alpha * cover(shadowDistance, max(px, 0.18 * shadowSize));
  float depth = -surface.x;
  if (coverage > 0.0 && depth < deepest) {
    liquid = vec4(lens.xyz, coverage);
    deepest = depth;
  }
}

// Each wiped point keeps its scene time. Completed chunks remain until the fog has returned;
// movement at the head cannot refresh the old tail or evict it while it is still clear.
void rainTrail(vec2 face, float px, float now, vec4 p0, vec4 p1, vec4 p2,
               vec4 t0, vec4 t1, vec4 t2, vec4 meta, float alpha,
               thread vec4& hit, thread vec4& next, thread vec2& near, thread float& wipe) {
  float r = meta.x;
  if (r <= 0.0 || alpha <= 0.0) return;
  vec2 pts[12];
  pts[0] = pathPoint(p0.x); pts[1] = pathPoint(p0.y); pts[2] = pathPoint(p0.z); pts[3] = pathPoint(p0.w);
  pts[4] = pathPoint(p1.x); pts[5] = pathPoint(p1.y); pts[6] = pathPoint(p1.z); pts[7] = pathPoint(p1.w);
  pts[8] = pathPoint(p2.x); pts[9] = pathPoint(p2.y); pts[10] = pathPoint(p2.z); pts[11] = pathPoint(p2.w);
  float times[12];
  times[0] = t0.x; times[1] = t0.y; times[2] = t0.z; times[3] = t0.w;
  times[4] = t1.x; times[5] = t1.y; times[6] = t1.z; times[7] = t1.w;
  times[8] = t2.x; times[9] = t2.y; times[10] = t2.z; times[11] = t2.w;
  float z = sqrt(max(0.04, 1.0 - dot(face, face)));
  float humidity = 6.0 + 2.0 * vnoise(face * 9.0);
  float closest = 1000.0;
  vec2 delta = vec2(0.0);
  vec2 tangent = vec2(0.0, -1.0);
  float deposited = 0.0;
  for (int k = 0; k < 11; k++) {
    if (float(k + 1) >= meta.z) break;
    vec2 seg = pts[k + 1] - pts[k];
    float len2 = dot(seg, seg);
    if (len2 < 0.000001) continue;
    float h = clamp(dot(face - pts[k], seg) / len2, 0.0, 1.0);
    vec2 d = face - pts[k] - seg * h;
    float distance = length(d);
    if (distance > r + px) continue;
    float age = max(0.0, now - mix(times[k], times[k + 1], h));
    float wet = 1.0 - smoothstep(0.35, humidity, age);
    float clearing = r * z * (0.72 + 0.13 * vnoise(face * 42.0)) * mix(0.45, 1.0, wet);
    wipe = max(wipe, alpha * wet * cover(distance - clearing, max(px, 0.08 * r)));
    // Choose the nearest centreline before ageing or shading it. Picking the freshest capsule
    // made every saved anchor produce a round lens endpoint and a regularly spaced optical rib.
    if (distance < closest) {
      closest = distance;
      delta = d;
      deposited = age;
      vec2 direction = seg / sqrt(len2);
      vec2 before = k > 0 ? pts[k] - pts[k - 1] : seg;
      vec2 after = float(k + 2) < meta.z ? pts[k + 2] - pts[k + 1] : seg;
      before /= max(length(before), 0.0001);
      after /= max(length(after), 0.0001);
      // Shared tangents round small bends without drawing a separate cap at every path sample.
      vec2 joined = mix(direction + before, direction + after, smoothstep(0.0, 1.0, h));
      tangent = length(joined) > 0.001 ? normalize(joined) : direction;
    }
  }
  if (closest < r + px) {
    vec2 centre = face - delta;
    // Deposited water pinches and spreads over fixed glass patches. The variation stays on the
    // glass as the head moves; a shallow transverse slope reads as film rather than a bead tube.
    float width = r * z * (0.08 + 0.12 * vnoise(centre * vec2(23.0, 17.0) + vec2(4.7, 9.2)));
    float fresh = 1.0 - smoothstep(0.15, 2.5, deposited);
    float film = alpha * fresh * cover(closest - width, px) * 0.5;
    if (film > 0.0) {
      vec2 across = vec2(-tangent.y, tangent.x);
      vec2 q = across * (dot(delta, across) / max(width, 0.0001)) * 0.3;
      consider(vec4(face - q * width, -width, film), closest / width, max(1.03, 1.0 + px / width), hit, next, near);
    }
  }
}


vec3 snowMaterial(float phase) {
  if (phase > 0.0) return vec3(1.0, 0.0, 0.0);
  float code = -phase - 1.0;
  float drive = floor(code / 262144.0);
  code -= drive * 262144.0;
  float compact = floor(code / 1024.0);
  return vec3((code - compact * 1024.0) / 1023.0, compact / 255.0, drive / 63.0);
}
float snowSegment(vec2 p, vec2 a, vec2 b) {
  vec2 d = b - a;
  return length(p - a - d * clamp(dot(p - a, d) / max(dot(d, d), 0.000001), 0.0, 1.0));
}
float snowCrystal(vec2 p, vec2 seed, float ice) {
  float family = hash2(seed + vec2(12.7, 31.9));
  float direction = floor((atan2(p.y, p.x) + 0.5235988) / 1.04719755);
  vec2 q = rotate2(p, -direction * 1.04719755);
  q.y = abs(q.y);
  vec2 armSeed = seed + vec2(mod(direction + 6.0, 6.0) * 13.1, 7.3);
  float arm = (0.72 + 0.28 * hash2(armSeed)) * (0.28 + 0.72 * ice);
  float thickness = (0.012 + 0.025 * hash2(seed + vec2(8.1, 3.6))) * smoothstep(0.0, 0.3, ice);
  float d = snowSegment(q, vec2(0.0), vec2(arm, 0.0)) - thickness;
  for (int k = 0; k < 4; k++) {
    float at = (0.17 + 0.16 * float(k)) * arm;
    float side = (0.09 + 0.21 * hash2(seed + vec2(float(k) * 4.7 + 15.9, 10.2)))
      * (1.0 - float(k) * 0.13) * smoothstep(0.15 + float(k) * 0.06, 0.75, ice);
    side *= 0.72 + 0.28 * hash2(armSeed + vec2(float(k) * 6.7, 12.3));
    d = min(d, snowSegment(q, vec2(at, 0.0), vec2(at + side * 0.5, side * 0.8660254)) - thickness * 0.62);
    if (family >= 0.24 && family <= 0.88) {
      for (int twig = 0; twig < 2; twig++) {
        float along = 0.38 + float(twig) * 0.3;
        vec2 base = vec2(at, 0.0) + vec2(0.5, 0.8660254) * side * along;
        float fine = side * (0.2 + 0.12 * hash2(armSeed + vec2(float(k), float(twig))))
          * smoothstep(0.45, 0.95, ice);
        d = min(d, snowSegment(q, base, base + vec2(fine, 0.0)) - thickness * 0.32);
      }
    }
  }
  // Plates, dendrites and rimed crystals share hexagonal geometry but have different cores.
  float core = (family < 0.24 ? 0.48 : (family > 0.88 ? 0.33 : 0.14)) * pow(max(ice, 0.0), 0.3333333);
  float hex = max(q.x * 0.8660254 + q.y * 0.5, q.y) - core;
  if (family < 0.24) d = min(d, hex);
  else d = min(d, length(p) - core * (0.8 + 0.2 * vnoise(p * 12.0 + seed)));
  return d;
}

// A shared height and gradient join nearby wet caps. Keep signed height outside each footprint
// so the smooth union can round a contact neck without creating a flat wet rectangle.
void snowWater(constant float4* uData, texture2d<float> uMedia, vec2 face, float px, float amount, thread vec4& liquid,
               thread float& deepest, thread float& shadow, thread float& wipe) {
  if (amount <= 0.0) return;
  vec3 surface = vec3(-1000.0, 0.0, 0.0);
  float size = 0.0;
  vec2 gravity = vec2(sin(uData[15].w * 0.01745329), -cos(uData[15].w * 0.01745329));
  for (int i = 0; i < 64; i++) {
    vec4 flake = uData[1240 + i];
    bool hail = flake.z < 0.0;
    if (hail ? uData[31].y < 0.5 : uData[28].w < 0.5) continue;
    if (flake.y <= 0.0 || flake.w > 0.0) continue;
    vec3 material = snowMaterial(flake.w);
    float radius = flake.y * 0.34 * pow(max(0.0, 1.0 - material.x), 0.3333333);
    if (radius < px * 0.1) continue;
    vec2 centre = pathPoint(flake.x);
    if (length(face - centre) > radius * 2.5 + px * 2.0) continue;
    vec3 field = dropField(face, vec3(centre, radius), vec3(gravity, material.z));
    if (material.x > 0.0 && !hail) {
      // Early meltwater fills the hollows between branches. Its angular pockets round out as
      // the ice support erodes. Transform the same analytic derivative into screen space.
      vec2 rel = face - centre;
      float radial = length(centre);
      vec2 axis = radial > 0.001 ? centre / radial : vec2(0.0, 1.0);
      float z = sqrt(max(0.025, 1.0 - dot(centre, centre)));
      vec2 tangent = rel + axis * dot(rel, axis) * (1.0 / z - 1.0);
      vec2 seed = vec2(mod(abs(flake.z), 4096.0), floor(abs(flake.z) / 4096.0));
      float turn = hash2(seed + vec2(7.3, 9.4)) * 6.2831853;
      float angle = 6.0 * (atan2(tangent.y, tangent.x) + turn);
      float pocket = radius * 0.14 * material.x * (1.0 - 0.5 * material.y);
      field.x += pocket * cos(angle);
      vec2 slope = vec2(-tangent.y, tangent.x) / max(dot(tangent, tangent), 0.000001);
      slope += axis * dot(slope, axis) * (1.0 / z - 1.0);
      field.yz -= pocket * 6.0 * sin(angle) * slope;
    }
    float t = 1.0 + field.x / radius;
    vec3 cap = vec3(0.5 * radius * (1.0 - t * t), -field.yz * t);
    float soft = max(px * 0.08, min(radius, max(size, radius)) * 0.16);
    float h = sat(0.5 + 0.5 * (surface.x - cap.x) / soft);
    surface = vec3(mix(cap.x, surface.x, h) + soft * h * (1.0 - h), mix(cap.yz, surface.yz, h));
    size = mix(radius, size, h);
    shadow *= 1.0 - 0.08 * amount * cover(field.x + radius * 0.12, max(px, radius * 0.12));
  }
  if (size <= 0.0) return;
  float alpha = amount * cover(-surface.x, max(px * 0.35, px * length(surface.yz))) * sat(size / px);
  float radial = length(face);
  alpha *= 1.0 - smoothstep(0.97, 1.06, radial);
  vec2 q = -surface.yz;
  vec2 axis = radial > 0.001 ? face / radial : vec2(0.0, 1.0);
  q += axis * dot(q, axis) * (max(0.025, 1.0 - dot(face, face)) - 1.0);
  q *= 0.8;
  wipe = max(wipe, alpha);
  if (alpha > 0.0 && -surface.x < deepest) {
    liquid = vec4(face - q * size, size, alpha);
    deepest = -surface.x;
  }
}

vec4 snowOver(constant float4* uData, texture2d<float> uMedia, vec4 c, vec2 face, float px, float level) {
  float amount = 1.0;
  if (amount <= 0.0) return c;
  vec3 incoming = lightDir(uData, uMedia);
  for (int i = 0; i < 64; i++) {
    vec4 flake = uData[1240 + i];
    bool hail = flake.z < 0.0;
    if (hail ? uData[31].y < 0.5 : uData[28].w < 0.5) continue;
    float radius = flake.y;
    if (radius <= 0.0) continue;
    vec2 centre = pathPoint(flake.x);
    if (length(face - centre) > radius * 1.4 + px) continue;
    vec3 material = snowMaterial(flake.w);
    if (material.x <= 0.0) continue;
    vec2 seed = vec2(mod(abs(flake.z), 4096.0), floor(abs(flake.z) / 4096.0));
    float height = max(0.0, flake.w - 1.0);
    vec2 p = (face - centre) / radius;
    float radial = length(centre);
    vec2 axis = radial > 0.001 ? centre / radial : vec2(0.0, 1.0);
    float z = sqrt(max(0.04, 1.0 - dot(centre, centre)));
    p += axis * dot(p, axis) * (mix(1.0 / z, 1.0, sat(height * 5.0)) - 1.0);
    float turn = hash2(seed + vec2(7.3, 9.4)) * 6.2831853 + height * (2.0 + hash2(seed) * 4.0);
    p = rotate2(p, turn);
    // An incoming plate tumbles out of plane and settles flat against the local glass.
    p.x /= mix(1.0, max(0.25, abs(cos(height * (8.0 + 4.0 * hash2(seed)) + turn))), sat(height * 5.0));
    // Compaction integrates dM/M. Undo its bulk radius growth for the original crystal,
    // which stays the same size while deposited material fills the porous space around it.
    float crystalScale = exp(-material.y);
    float crystal = hail ? length(p) - pow(material.x,0.3333333) * (0.88+0.08*vnoise(p*7.0+seed)) : snowCrystal(p / crystalScale, seed, material.x) * crystalScale;
    float mound = length(p) - (0.95 + 0.11 * (vnoise(p * 5.0 + seed) - 0.5)) * pow(material.x, 0.3333333);
    // Packing gradually buries individual branches into a granular deposit, retaining both
    // surfaces through the transition rather than exchanging a flake sprite for a blob.
    float alpha = mix(cover(crystal, px / radius), cover(mound, px / radius), material.y);
    alpha *= amount * smoothstep(0.0, 0.03, material.x) * (1.0 - smoothstep(0.98, 1.08, length(face)));
    alpha *= 1.0 - 0.32 * sat(height * 2.0);
    float grain = vnoise(p * 36.0 + seed) * (1.0 - smoothstep(0.03, 0.2, px / radius));
    vec3 normal = normalize(vec3(centre, z) + vec3(rotate2(vec2(0.1, 0.03), turn), 0.0));
    float illumination = 0.78 + 0.22 * max(0.0, dot(normal, incoming));
    // Thin ice transmits the view; edges, growth ridges and packed grains scatter more light.
    float edge = 1.0 - smoothstep(0.008, 0.045, max(0.0, -crystal));
    float a = atan2(p.y, p.x);
    float folded = mod(a + 0.5235988, 1.04719755) - 0.5235988;
    vec2 q = vec2(length(p) * cos(folded), abs(length(p) * sin(folded)));
    float hex = max(q.x * 0.8660254 + q.y * 0.5, q.y);
    float ridges = exp(-abs(sin(hex * (36.0 + 20.0 * hash2(seed + vec2(9.2, 6.7))))) * 18.0)
      * (1.0 - smoothstep(0.35, 0.65, length(p))) * material.x;
    float scattering = hail ? 0.4 + 0.28*grain + 0.15*max(0.0,1.0-length(p)) : mix(0.42 + 0.48 * edge + 0.1 * ridges, 0.96, material.y);
    vec3 ice = (hail ? vec3(uData[39].z, uData[39].w, uData[40].x) : uData[27].xyz) * illumination * (0.94 + grain * 0.06);
    c = over(c, vec3(0.17, 0.22, 0.29), alpha * 0.1);
    c = over(c, ice, alpha * scattering);
  }
  return c;
}


// The rain at face, before what is behind the glass is drawn. Returns the water face is in, as a
// lens: centre, radius (negative for a streak's film, which catches no glint), and the share of
// face it covers, where the centre is set so that (face - centre) / |radius| is the slope of the
// water at face (for a round drop, just where face is in it). In marks: how clear the running
// drops' paths leave the fog (x) and the mist (y), the light the shadows leave (z), and the light
// the clearer paths the mark draws above its running drops leave (w).
vec4 rainScan(constant float4* uData, texture2d<float> uMedia, vec2 face, float px, vec4 clock, thread vec4& marks) {
  float amount = uData[14].z;
  vec4 hit = vec4(0.0);
  marks = vec4(0.0, 0.0, 1.0, 1.0);
  vec4 next = vec4(0.0);
  vec2 near = vec2(1000.0);
  float shadow = 1.0;
  float wipe = 0.0;
  vec4 counts = uData[47];
  if ((mod(floor(uData[3].w / 1.0), 2.0) > 0.5) || (mod(floor(uData[3].w / 2.0), 2.0) > 0.5) || (mod(floor(uData[45].z / 128.0), 2.0) > 0.5)) {
  for (int i = 0; i < 48; i++) {
    vec4 meta = uData[856 + i * 8 + 6];
    if (meta.x <= 0.0 || meta.z < 2.0) continue;
    vec4 box = uData[856 + i * 8 + 7];
    float reach = meta.x + px;
    if (face.x < box.x - reach || face.y < box.y - reach || face.x > box.z + reach || face.y > box.w + reach) continue;
    float alpha = meta.y == -3.0 ? uData[31].y : meta.y == -2.0 ? uData[28].w : uData[28].z;
    rainTrail(face, px, clock.x,
      uData[856 + i * 8],
      uData[856 + i * 8 + 1],
      uData[856 + i * 8 + 2],
      uData[856 + i * 8 + 3],
      uData[856 + i * 8 + 4],
      uData[856 + i * 8 + 5],
      meta, alpha, hit, next, near, wipe);
  }
  }
  vec4 liquid = vec4(0.0);
  float deepest = 1000.0;
  if ((mod(floor(uData[3].w / 65536.0), 2.0) > 0.5)) {
  for (int i = 0; i < 384; i++) {
    vec4 pool = uData[88 + i * 2];
    if (pool.y <= 0.0 || pool.z < 0.0) continue;
    float alpha = i < 16 ? sat(amount * counts.x - float(i)) : 1.0;
    vec4 other = vec4(0.0);
    vec4 cached = uData[88 + i * 2 + 1];
    if (cached.y > 0.0) {
      vec4 pair = cached;
      float partnerAlpha = pair.z < 0.0 ? 1.0 : sat(amount * counts.x - pair.z);
      other = vec4(pathPoint(pair.x), pair.y, partnerAlpha);
    }
    vec2 shapes = vec2(abs(pool.z) - 1.0, cached.w);
    sphereWater(face, px, vec4(pathPoint(pool.x), pool.y, alpha), other, pool.w, shapes,
                liquid, deepest, shadow);
  }
  }
  if ((mod(floor(uData[3].w / 131072.0), 2.0) > 0.5)) {
  snowWater(uData, uMedia, face, px, 1.0, liquid, deepest, shadow, wipe);
  }
  marks = vec4(wipe, wipe, shadow, 1.0);
  return liquid.w > 0.0 ? liquid : water(face, px, hit, next, near);
}

// A bead of mist (x, y, radius) over c, a how much of it shows.
vec4 mistBead(vec4 c, vec3 bead, float a, vec2 face, float px, vec3 shade) {
  float d = length(face - bead.xy);
  if (a <= 0.0 || d > bead.z + px) return c;
  // Lit up and to the left, shaded at the far edge.
  float g = length(face - bead.xy - vec2(-0.2, 0.3) * bead.z) / bead.z;
  vec3 tint = vec3(1.0);
  float tintA = 0.0;
  if (g < 0.55) {
    float t = g / 0.55;
    tint = mix(vec3(1.0), vec3(1.0, 0.824, 0.69), t);
    tintA = mix(0.9, 0.3, t);
  } else {
    float t = sat((g - 0.55) / 0.45);
    tint = mix(vec3(1.0, 0.824, 0.69), min(shade * 2.0, vec3(1.0)), t);
    tintA = mix(0.3, 0.25, t);
  }
  return over(c, tint, tintA * a * cover(d - bead.z, px));
}

// The rain over the glass, from rainScan: the clearer paths the mark draws, every drop's shadow,
// the water this point is in (hit, its alpha how much of the point it covers) with seen what its
// lens gathers, and the mist of beads, gone where a drop has run through it.
vec4 rain(constant float4* uData, texture2d<float> uMedia, vec4 c, vec2 face, float px, vec4 hit, vec3 seen, vec4 marks) {
  float mist = 0.0;
  if ((mod(floor(uData[3].w / 16.0), 2.0) > 0.5)) { mist = uData[14].w; }
  if (hit.w <= 0.0 && mist <= 0.0 && marks.z >= 1.0 && marks.w >= 1.0) return c;
  vec3 shade = uData[16].yzw;
  c = over(c, vec3(1.0), 1.0 - marks.w);
  c = over(c, shade, 1.0 - marks.z);

  if (hit.w > 0.0) {
    float size = abs(hit.z);
    vec2 q = (face - hit.xy) / size;
    float kq = length(q);
