vec4 sunny(constant float4* uData, texture2d<float> uMedia, vec4 c, vec2 face, float px, float level, vec4 water) {
  float amount = sat(uData[18].y + uData[24].x * level);
  if (((mod(floor(uData[45].z / 2.0), 2.0) > 0.5)) && (uData[30].z > 0.0)) { amount *= exp(-cloudDensity(uData, uMedia, face,uData[1].x) * uData[32].y * 3.0); }
  if (amount <= 0.0) return c;
