}

// The room mirrored in the glass, the light's softbox included, by Fresnel: faint face on,
// strong at the rim.
vec4 mirror(constant float4* uData, texture2d<float> uMedia, vec4 c, vec2 face, float blur, vec4 clock) {
  float amount = uData[6].z;
