  vec4 marks = vec4(0.0, 0.0, 1.0, 1.0);
  vec4 drop = vec4(0.0);
  if ((mod(floor(uData[3].w / 1.0), 2.0) > 0.5) || (mod(floor(uData[3].w / 2.0), 2.0) > 0.5) || (mod(floor(uData[45].z / 128.0), 2.0) > 0.5)) { drop = rainScan(uData, uMedia, f, px, clock, marks); }
