  if ((mod(floor(uData[3].w / 1.0), 2.0) > 0.5) || (mod(floor(uData[3].w / 2.0), 2.0) > 0.5) || (mod(floor(uData[45].z / 128.0), 2.0) > 0.5)) { c = rain(uData, uMedia, c, f, px, drop, seen, marks); }
  if ((mod(floor(uData[3].w / 16.0), 2.0) > 0.5)) { if (!((mod(floor(uData[3].w / 1.0), 2.0) > 0.5) || (mod(floor(uData[3].w / 2.0), 2.0) > 0.5) || (mod(floor(uData[45].z / 128.0), 2.0) > 0.5))) c = rain(uData, uMedia, c, f, px, drop, seen, marks); }
  if ((mod(floor(uData[3].w / 8.0), 2.0) > 0.5)) { c = sunny(uData, uMedia, c, f, px, level, drop); }
  if (((mod(floor(uData[3].w / 32.0), 2.0) > 0.5)) && (uData[6].z > 0.0)) { c = mirror(uData, uMedia, c, f, uData[5].y * 0.12, clock); }
  c = glass(uData, uMedia, c, f, r, px);
  if (((mod(floor(uData[45].z / 8.0), 2.0) > 0.5)) && (uData[31].x > 0.0)) { c = weatherLightning(uData, uMedia, c,f,px,clock); }
  if (((mod(floor(uData[45].z / 16.0), 2.0) > 0.5)) && (uData[31].z > 0.0)) { c = frostWeather(uData, uMedia, c,f,px,clock.x); }
  if (((mod(floor(uData[45].z / 64.0), 2.0) > 0.5)) && (uData[31].w > 0.0)) { c = airborneWeather(uData, uMedia, c,f,px,clock.x); }
