  }
  c.rgb = clamp(c.rgb, vec3(0.0), vec3(c.a));
  return c * coverage + under * (1.0 - c.a * coverage);
}

struct OrbVertexOut {
  float4 position [[position]];
};

// One triangle that covers the drawable, from the vertex id alone.
vertex OrbVertexOut orbVertex(uint id [[vertex_id]]) {
  float2 p = float2(float((id << 1) & 2), float(id & 2));
  OrbVertexOut out;
  out.position = float4(p * 2.0 - 1.0, 0.0, 1.0);
  return out;
}

// Metal's origin is the top-left corner, so turn y back up before drawing.
fragment float4 orbFragment(OrbVertexOut in [[stage_in]], constant float4* uData [[buffer(0)]], texture2d<float> uMedia [[texture(0)]]) {
  return orb(uData, uMedia, float2(in.position.x, uData[0].y - in.position.y));
}
