  return over(c, vec3(uData[7].w, uData[8].x, uData[8].y), sat((0.25 + fresnel) * 3.0 * amount * softbox(uData, d, blur)));
}

vec4 glass(constant float4* uData, vec4 c, vec2 face, float r, float px) {
  // Light bounced up along the bottom of the glass: a soft arc from -139° to -41°.
  if (((mod(floor(uData[3].w / 2048.0), 2.0) > 0.5)) && (uData[10].x > 0.0)) {
  float angle = atan2(face.y, face.x) * 57.29578;
  float along = smoothstep(-149.0, -131.0, angle) * (1.0 - smoothstep(-49.0, -31.0, angle));
  float band = exp(-((r - 0.94) / 0.1) * ((r - 0.94) / 0.1));
  c = over(c, uData[10].yzw, sat(uData[10].x * 0.2 * band * along));

