  vec4 c = vec4(col * opacity, opacity);
  c = over(c, uData[9].xyz, uData[8].w * sat((r - 0.72) / 0.28));
  if ((mod(floor(uData[3].w / 4.0), 2.0) > 0.5)) { c = fogOver(uData, c, f, fog, px); }
  if ((mod(floor(uData[3].w / 1.0), 2.0) > 0.5) || (mod(floor(uData[3].w / 2.0), 2.0) > 0.5) || (mod(floor(uData[50].z / 128.0), 2.0) > 0.5)) { c = rain(uData, c, f, px, drop, seen, marks); }
  if ((mod(floor(uData[3].w / 16.0), 2.0) > 0.5)) { if (!((mod(floor(uData[3].w / 1.0), 2.0) > 0.5) || (mod(floor(uData[3].w / 2.0), 2.0) > 0.5) || (mod(floor(uData[50].z / 128.0), 2.0) > 0.5))) c = rain(uData, c, f, px, drop, seen, marks); }
  if ((mod(floor(uData[3].w / 8.0), 2.0) > 0.5)) { c = sunny(uData, c, f, px, level, drop); }
  if (((mod(floor(uData[3].w / 32.0), 2.0) > 0.5)) && (uData[6].z > 0.0)) { c = mirror(uData, c, f, uData[5].y * 0.12, clock); }
  c = glass(uData, c, f, r, px);
  if (((mod(floor(uData[50].z / 8.0), 2.0) > 0.5)) && (uData[31].x > 0.0)) { c = weatherLightning(uData, c,f,px,clock); }
  if (((mod(floor(uData[50].z / 16.0), 2.0) > 0.5)) && (uData[31].z > 0.0)) { c = frostWeather(uData, c,f,px,clock.x); }
  if (((mod(floor(uData[50].z / 64.0), 2.0) > 0.5)) && (uData[31].w > 0.0)) { c = airborneWeather(uData, c,f,px,clock.x); }
  if ((mod(floor(uData[3].w / 131072.0), 2.0) > 0.5)) { c = snowOver(uData, c, f, px, level); }

  if ((mod(floor(uData[3].w / 1024.0), 2.0) > 0.5)) {
