us = next;\\n  }\\n  return paintRGB(previous.z);\\n}\\nvec3 paintField0(vec2 p) {\\n    vec3 color = vec3(0.0); float total = 0.0;\\n    float w0 = max(0.0, uPaint0[0].x);\\n        if (w0 > 0.00001) { color += w0 * paintSample(uPaint0[2], uPaint0[3], uPaint0[4], uPaint0[5], uPaint0[6], uPaint0[7], uPaint0[8], uPaint0[9], uPaint0[10], uPaint0[11], p); total += w0; }\\nfloat w1 = max(0.0, uPaint0[0].y);\\n        if (w1 > 0.00001) { color += w1 * paintSample(uPaint0[2], uPaint0[3], uPaint0[4], uPaint0[5], uPaint0[6], uPaint0[7], uPaint0[8], uPaint0[9], uPaint0[10], uPaint0[11], p); total += w1; }\\nfloat w2 = max(0.0, uPaint0[0].z);\\n        if (w2 > 0.00001) { color += w2 * paintSample(uPaint0[2], uPaint0[3], uPaint0[4], uPaint0[5], uPaint0[6], uPaint0[7], uPaint0[8], uPaint0[9], uPaint0[10], uPaint0[11], p); total += w2; }\\nfloat w3 = max(0.0, uPaint0[0].w);\\n        if (w3 > 0.00001) { color += w3 * paintSample(uPaint0[2], uPaint0[3], uPaint0[4], uPaint0[5], uPaint0[6], uPaint0[7], uPaint0[8], uPaint0[9], uPaint0[10], uPaint0[11], p); total += w3; }\\nfloat w4 = max(0.0, uPaint0[1].x);\\n        if (w4 > 0.00001) { color += w4 * paintSample(uPaint0[2], uPaint0[3], uPaint0[4], uPaint0[5], uPaint0[6], uPaint0[7], uPaint0[8], uPaint0[9], uPaint0[10], uPaint0[11], p); total += w4; }\\n    return color / max(total, 0.00001);\\n  }\\n\\nfloat sat(float x) { return clamp(x, 0.0, 1.0); }\\n\\n// Coverage of a shape whose signed distance is d, softened over w either side of its edge.\\nfloat cover(float d, float w) { return 1.0 - smoothstep(-w, w, d); }\\n\\n// v folded into [lo, hi), for things that drift off one side and come back on the other.\\nfloat wrapf(float v, float lo, float hi) {\\n  float span = hi - lo;\\n  return v - span * floor((v - lo) / span);\\n}\\n\\nfloat boxSdf(vec2 p, vec2 extent) {\\n  vec2 q = abs(p) - extent;\\n  return length(max(q, vec2(0.0))) + min(max(q.x, q.y), 0.0);\\n}\\n\\n\\n\\n// A hash of a point without sin, which stays steady on mobile GPUs.\\nfloat hash2(vec2 p) {\\n  vec3 q = fract(vec3(p.x, p.y, p.x) * 0.1031);\\n  q += dot(q, vec3(q.y, q.z, q.x) + 33.33);\\n  return fract((q.x + q.y) * q.z);\\n}\\n\\n// Smooth value noise, 0 to 1.\\nfloat vnoise(vec2 p) {\\n  vec2 i = floor(p);\\n  vec2 f = fract(p);\\n  vec2 u = f * f * (3.0 - 2.0 * f);\\n  float a = hash2(i);\\n  float b = hash2(i + vec2(1.0, 0.0));\\n  float c = hash2(i + vec2(0.0, 1.0));\\n  float d = hash2(i + vec2(1.0, 1.0));\\n  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);\\n}\\n\\n// Value noise summed over octaves, each twice as fine and turned. octaves is at most 7.\\nfloat fbm(vec2 p, int octaves) {\\n  float sum = 0.0;\\n  float amp = 0.5;\\n  for (int i = 0; i < 7; i++) {\\n    if (i >= octaves) break;\\n    sum += amp * vnoise(p);\\n    p = vec2(1.6 * p.x - 1.2 * p.y, 1.2 * p.x + 1.6 * p.y);\\n    amp *= 0.5;\\n  }\\n  return sum;\\n}\\n\\nvec2 rotate2(vec2 p, float a) {\\n  float c = cos(a);\\n  float s = sin(a);\\n  return vec2(c * p.x - s * p.y, s * p.x + c * p.y);\\n}\\n\\n// Premultiplied c with x laid over it at opacity a.\\nvec4 over(vec4 c, vec3 x, float a) { return vec4(mix(c.rgb, x, a), mix(c.a, 1.0, a)); }\\n\\n// Where a scene point d from the centre lands on the face (see lens.ts).\\nfloat bendRadius(float d, float bend) {\\n  float bent = d <= 1.0 ? sin(d * 1.5707963) : 1.0 + (d - 1.0) * 0.08;\\n  return (1.0 - bend) * d + bend * bent;\\n}\\n\\n// The glass, inverted: the scene point that shows at this point of the face, and how much the\\n// glass magnifies there (scene units per face unit is its reciprocal).\\nvec3 unbend(vec2 face, float bend) {\\n  if (bend <= 0.00001) return vec3(face, 1.0);\\n  float rho = length(face);\\n  float d = min(rho, 1.0);\\n  for (int i = 0; i < 5; i++) {\\n    float f = (1.0 - bend) * d + bend * sin(d * 1.5707963) - rho;\\n    float df = (1.0 - bend) + bend * 1.5707963 * cos(d * 1.5707963);\\n    d = clamp(d - f / max(df, 0.001), 0.0, 1.0);\\n  }\\n  float gain = max((1.0 - bend) + bend * 1.5707963 * cos(d * 1.5707963), 0.001);\\n  vec2 s = rho > 0.00001 ? face * (d / rho) : face / ((1.0 - bend) + bend * 1.5707963);\\n  return vec3(s, gain);\\n}\\n\\n// Where the light is: the direction the view reflects to off the glass at the light's highlight.\\nvec3 lightDir() {\\n  vec2 at = vec2(uData[7].y, uData[7].z);\\n  float radius = length(at);\\n  vec2 direction = radius > 0.00001 ? at / radius : vec2(0.0, 1.0);\\n  // Extend the source beyond the glass without a zero half-vector at the rim. The elevation\\n  // offset changes incidence independently of the source's visible glare position.\\n  float r = min(radius, 0.999);\\n  float z = sqrt(1.0 - r * r);\\n  vec3 natural = vec3(2.0 * z * r * direction, 1.0 - 2.0 * r * r);\\n  if (abs(uData[24].w) < 0.00001) return natural;\\n  float elevation = clamp(asin(clamp(natural.z, -1.0, 1.0)) + uData[24].w * 0.01745329,\\n    -1.526326, 1.5707963);\\n  return normalize(vec3(direction * cos(elevation), sin(elevation)));\\n}\\n\\n// The light's specular point on the sphere, distinct from its source position outside the orb.\\nvec2 lightSpot() {\\n  return normalize(lightDir() + vec3(0.0, 0.0, 1.0)).xy;\\n}\\n\\n// How bright the light's softbox is along d, 0 to 1, softened by blur.\\n\\n\\n// The room round the orb, by direction (y up, z toward the viewer): a sweep of wall over a floor,\\n// with tall softboxes round it, which show the room turning as it turns. The eye looks a little\\n// down on the orb, so behind it is floor and the horizon curves through the glass. spin turns the\\n// room (radians) and blur softens it.\\nvec3 room(vec3 d, float blur, float spin) {\\n  vec3 t = vec3(d.x, d.y * 0.9689 + d.z * 0.2474, d.z * 0.9689 - d.y * 0.2474);\\n  vec2 xz = rotate2(vec2(t.x, t.z), spin);\\n  vec3 q = vec3(xz.x, t.y, xz.y);\\n  vec3 col = mix(vec3(uData[12].w, uData[13].x, uData[13].y), uData[12].xyz, smoothstep(0.0, 0.75 + blur, q.y));\\n  col = mix(col, vec3(uData[13].z, uData[13].w, uData[14].x), smoothstep(-0.015 - blur, 0.45 + blur, -q.y));\\n  col *= 1.0 - 0.3 * smoothstep(0.45, 1.0, -q.y);\\n  float around = atan(q.x, 0.000001 - q.z);\\n  float cell = abs(around - 2.0943951 * floor(around / 2.0943951 + 0.5));\\n  float panel = (1.0 - smoothstep(0.26, 0.32 + blur, cell))\\n    * smoothstep(0.04, 0.09 + blur, q.y) * (1.0 - smoothstep(0.5, 0.56 + blur, q.y));\\n  return mix(col, mix(uData[12].xyz, vec3(1.0), 0.85), panel);\\n}\\n\\n// Which way a ray along -z leaves a solid ball of glass through this point of its face: bent in\\n// at the front and out at the back, so what is behind the ball shows upside down.\\nvec3 throughBall(vec2 face, float ior) {\\n  vec3 p = vec3(face, sqrt(max(0.0, 1.0 - dot(face, face))));\\n  vec3 d = refract(vec3(0.0, 0.0, -1.0), p, 1.0 / ior);\\n  vec3 q = p - 2.0 * dot(p, d) * d;\\n  vec3 o = refract(d, -q, ior);\\n  return dot(o, o) > 0.5 ? o : reflect(d, -q);\\n}\\n\\nfloat weatherWind(float time) {\\n  float envelope = 0.5 + 0.28 * sin(time * 0.73) + 0.22 * sin(time * 1.37 + 1.9);\\n  return uData[29].z + max(0.0, uData[29].w - uData[29].z) * envelope * uData[30].x;\\n}\\n\\n// One pulse per seeded interval; never a rapid sequence of strobe flashes.\\n\\n// Connected, irregular channels with narrower forks and a separate scattered-light halo.\\n// Visual reference: Kim & Lin, Physically Based Animation and Rendering of Lightning (2004).\\n// This bounded analytic tree avoids running their dielectric-breakdown simulation per pixel.\\n\\n\\n\\n\\n\\nvec4 weatherSky(vec4 c, vec2 p, float px, vec4 clock) {\\n  float daylight = 1.0;\\n  \\n  \\n  return c;\\n}\\n\\nvec4 airborneWeather(vec4 c, vec2 p, float px, float time) {\\n  float rain = uData[28].z * uData[15].x;\\n  float snow = uData[28].w * sat(uData[25].x + uData[27].w * uData[0].z) * uData[25].y;\\n  float hail = uData[31].y * uData[38].y * uData[38].z;\\n  if (rain + snow + hail <= 0.0) return c;\\n  float strength = weatherWind(time);\\n  float movement = 1.0 - uData[30].y;\\n  // Separate streams keep mixed precipitation and individual incoming angles independent.\\n  // Empty streams skip their grids entirely.\\n  for (int kind = 0; kind < 3; kind++) {\\n    float intensity = kind == 0 ? rain : (kind == 1 ? snow : hail);\\n    if (intensity <= 0.0) continue;\\n    float offset = kind == 0 ? uData[24].z : (kind == 1 ? uData[25].w : 0.0);\\n    float angle = clamp(uData[28].x + offset, -80.0, 80.0) * 0.01745329;\\n    vec2 down = vec2(sin(angle), -cos(angle));\\n    float pace = kind == 0 ? 1.25 : (kind == 1 ? 0.22 * uData[26].x : 1.8);\\n    for (int layer = 0; layer < 3; layer++) {\\n      float z = (float(layer) + 0.4) / 3.0;\\n      float depth = mix(1.0, z, uData[42].x);\\n      float grid = 7.0 + float(layer) * 6.0;\\n      vec2 shift = down * (time * pace * (0.65 + depth * 0.45) + uData[2].z * 0.035) * movement;\\n      shift.x += sin(time*0.7 + z*5.0) * uData[30].x * strength * (kind == 1 ? 0.008 : 0.002) * movement;\\n      vec2 q = (p - shift) * grid;\\n      vec2 cell = floor(q);\\n      for (int neighbor = 0; neighbor < 9; neighbor++) {\\n        vec2 tile = cell + vec2(float(neighbor - 3*(neighbor/3)) - 1.0, float(neighbor/3) - 1.0);\\n        vec2 key = tile + vec2(z*79.3 + float(kind)*117.1, z*21.1 + float(kind)*31.7);\\n        float seed = hash2(key);\\n        if (seed > intensity * 0.8) continue;\\n        vec2 at = tile + vec2(hash2(key+vec2(13.1,z)), hash2(key+vec2(z,9.7)));\\n        vec2 rel = (q-at) / grid;\\n        float alpha = 0.0;\\n        vec3 color = uData[27].xyz;\\n        if (kind == 0) {\\n          vec2 line = down * (0.025 + depth * 0.09) * uData[28].y;\\n          float h = sat(dot(rel,line) / max(dot(line,line),0.000001));\\n          float d = length(rel-line*h);\\n          alpha = cover(d - (0.00065+depth*0.0015)*uData[28].y,px) * 0.28 * depth;\\n          color = mix(uData[27].xyz, vec3(0.72,0.82,0.9),0.75);\\n        } else if (kind == 1) {\\n          float radius = (0.004+depth*0.009) * uData[26].y * (0.7 + seed*0.5);\\n          vec2 flake = rotate2(rel / radius, seed*6.283 + time*(seed-0.5)*movement);\\n          float a = atan(flake.y,flake.x);\\n          float branches = 0.6 + 0.25*cos(a*6.0) + 0.08*cos(a*12.0+seed*8.0);\\n          alpha = cover(length(flake)-branches,px/radius) * 0.7 * depth;\\n        } else {\\n          alpha = cover(length(rel)-(0.003+depth*0.007)*uData[38].w,px) * 0.85 * depth;\\n          color = vec3(uData[39].z, uData[39].w, uData[40].x);\\n        }\\n        c = over(c,color,alpha*uData[41].w);\\n      }\\n    }\\n  }\\n  return c;\\n}\\nvec4 frostWeather(vec4 c, vec2 p, float px, float time) {\\n  float amount = uData[57].w;\\n  if (amount <= 0.0) return c;\\n  float patches = fbm(p*5.0,5);\\n  float edge = pow(sat(dot(p,p)),2.0);\\n  float glaze = smoothstep(0.9-amount*0.85,1.05-amount*0.65,patches+edge*0.4);\\n  float angle = atan(p.y,p.x);\\n  float crystals = pow(max(0.0,sin(angle*18.0+fbm(p*9.0,3)*6.0)),12.0) * edge;\\n  float scatter = mix(0.15,0.75,uData[40].z);\\n  float grain = vnoise(p*120.0) * (1.0-smoothstep(0.003,0.012,px));\\n  c = over(c,uData[41].xyz,glaze*(scatter+grain*0.12));\\n  c.rgb += uData[41].xyz * crystals * glaze * 0.09;\\n  return c;\\n}\\n\\n// The sky's gradient at t, from the horizon's glow (0) to the zenith (1).\\nvec3 sky(vec2 s) {\\n  float t = sat((s.y - uData[49].w) / max(uData[50].x, 0.001));\\n  vec2 skyPoint = vec2(s.x, 2.0 * t - 1.0);\\n  return paintField0(skyPoint);\\n}\\n\\n// Where the sun shows on the face, which the glow is centred on and the drops look toward.\\nvec2 sunFace() {\\n  vec2 sun = vec2(uData[50].y, uData[50].z);\\n  float d = length(sun);\\n  return d > 0.000000001 ? sun * (bendRadius(d, uData[4].z) / d) : vec2(0.0);\\n}\\n\\n// The sun's glow is a radial gradient on the face, not in the scene, as in the mark.\\nvec4 glow(vec2 face, float level) {\\n  float g = length(face - sunFace()) / max(uData[52].x, 0.001);\\n  float amount = max(0.0, uData[51].w + uData[56].z * level);\\n  if (g < 0.35) {\\n    float k = g / 0.35;\\n    return vec4(mix(uData[52].yzw, uData[53].xyz, k), mix(0.95, 0.55, k) * amount);\\n  }\\n  float k = sat((g - 0.35) / 0.65);\\n  return vec4(mix(uData[53].xyz, vec3(uData[53].w, uData[54].x, uData[54].y), k), mix(0.55, 0.0, k) * amount);\\n}\\n\\n// A cloud's puff p (x, y, radius), the i-th, folded into its body, underside and crown distances.\\nvec3 cloudPuff(vec3 sd, vec3 p, float i, vec2 s, vec2 low, float shift, float billow, vec4 clock) {\\n  // Each puff swells and settles on its own phase, so the cloud boils rather than pulses.\\n  float phase = i * 1.7;\\n  vec2 at = vec2(p.x + shift, p.y + billow * 0.014 * sin(clock.x * 0.7 + phase * 1.3));\\n  float r = p.z * (1.0 + billow * 0.08 * sin(clock.x * 0.9 + phase));\\n  return vec3(\\n    min(sd.x, length(s - at) - r),\\n    min(sd.y, length(low - at) - r),\\n    min(sd.z, length(s - at - vec2(-0.03, 0.05)) - 0.62 * r)\\n  );\\n}\\n\\n// A bank's puff p folded into its body and crest distances.\\nvec2 bankPuff(vec2 bc, vec3 p, vec2 s, float drift, float extent, float swell, float b, vec4 clock) {\\n  float x = wrapf(p.x + drift, -extent, extent);\\n  // A swell travels along the bank.\\n  vec2 at = vec2(x, p.y + swell * 0.035 * sin(clock.x * 0.8 + x * 2.5 + b * 1.3));\\n  return vec2(min(bc.x, length(s - at) - p.z), min(bc.y, length(s - at - vec2(-0.012, 0.022)) - p.z));\\n}\\n\\n// The flat picture at scene point s. face is where it shows (for the glow), w the anti-aliasing\\n// width and k scene units per face unit there, so the picture's own softness stays the same size\\n// on the face however hard the glass bends it.\\nvec3 scene(vec2 s, vec2 face, float w, float k, float level, vec4 clock, vec4 m) {\\n  vec3 col = sky(s);\\n  vec4 gl = glow(face, level);\\n  col = mix(col, gl.rgb, sat(gl.a));\\n  vec2 sun = vec2(uData[50].y, uData[50].z);\\n  col = mix(col, uData[51].xyz, cover(length(s - sun) - uData[50].w, w));\\n\\n  vec